import {terrainSVG,creekSVG} from './art.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=new URLSearchParams(location.search).has('fresh');
const showcase=new URLSearchParams(location.search).has('showcase');
const storageKey=`aumanet-independent-v${SCHEMA}${fresh?'-fresh':''}`;
let state,storageAvailable=true;
try{const stored=showcase?null:JSON.parse(localStorage.getItem(storageKey));state=stored?.schema===SCHEMA?stored:initialState({fresh});if(stored&&(stored.connection.run||stored.voice.joined||stored.location.sharing))state=transition(state,'restart');}catch{state=initialState({fresh});storageAvailable=false;}
let modal=null,toastTimer,mapView={zoom:1,x:0,y:0},photoReview=null,plannerResult=null,selectedResult=null;
const plannerDefaults={upload:412,download:468,members:4,talkers:2,voiceRate:24,overhead:1.35,interval:10,messages:2,hops:1,reserve:30,other:10,donor:0,photo:.75,map:43,web:1.5,historical:false};
let plannerInputs={...plannerDefaults};
const paths={field:'M3 11l9-7 9 7v9H3z M9 20v-7h6v7',chat:'M21 11a8 8 0 0 1-8 8H8l-5 3 1-6a8 8 0 1 1 17-5z M8 10h8 M8 13h5',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2z M9 3v16 M15 5v16',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',kit:'M4 7h16v14H4z M8 7V3h8v4 M4 12h16 M10 12v3h4v-3',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',close:'m6 6 12 12 M18 6 6 18',check:'m5 12 4 4L19 6',double:'m2 12 4 4L16 6 M10 16 20 6',mic:'M9 3h6v10H9z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',muted:'m3 3 18 18 M9 9v4h5 M9 5V3h6v8 M5 10v2a7 7 0 0 0 12 5 M19 10v2 M12 19v3 M8 22h8',volume:'M11 5 6 9H2v6h4l5 4z M15 8a6 6 0 0 1 0 8 M18 5a10 10 0 0 1 0 14',volumeOff:'M11 5 6 9H2v6h4l5 4z m5 4 6 6 M22 9l-6 6',wifi:'M2 8a15 15 0 0 1 20 0 M5 12a10 10 0 0 1 14 0 M8 16a5 5 0 0 1 8 0 M12 20h.01',radio:'M12 19v3 M8 22h8 M12 5a7 7 0 0 1 0 14 7 7 0 0 1 0-14 M12 9a3 3 0 0 1 0 6 3 3 0 0 1 0-6 M2 4a14 14 0 0 0 0 16 M22 4a14 14 0 0 1 0 16',location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z M12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6',target:'M12 2v4 M12 18v4 M2 12h4 M18 12h4 M12 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M12 10a2 2 0 1 0 0 4 2 2 0 0 0 0-4',download:'M12 3v12 m-5-5 5 5 5-5 M3 16v5h18v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M3 16v5h18v-5',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3a17 17 0 0 1 0 18 17 17 0 0 1 0-18',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7z m-5 9 3 3 6-6',phone:'M7 2h10v20H7z M11 18h2',node:'M6 7h12v14H6z M15 7V1 M9 11h6 M9 14h6 M11 18h2',settings:'M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-4-1V8l4-1z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',bell:'M18 8a6 6 0 0 0-12 0v7l-2 3h16l-2-3z M10 21h4',send:'m3 3 19 9-19 9 4-9z M7 12h15',photo:'M3 3h18v18H3z m0 13 6-6 6 6 3-3 3 3 M16 6h.01',paperclip:'m8 12 6-6a3 3 0 0 1 4 4l-9 9a5 5 0 0 1-7-7L13 1 M6 14l8-8',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 6v6l4 2',more:'M5 12h.01 M12 12h.01 M19 12h.01',copy:'M9 9h12v12H9z M5 15H3V3h12v2',refresh:'M21 7v6h-6 M3 17v-6h6 M5.5 6a8 8 0 0 1 13 0L21 9 M3 15l2.5 3a8 8 0 0 0 13 0',stop:'M5 5h14v14H5z',pause:'M6 4h4v16H6z M14 4h4v16h-4z',play:'m7 3 14 9-14 9z',test:'M3 20h18 M6 16V8 M12 16V3 M18 16v-5',sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2',moon:'M21 13A9 9 0 1 1 11 3a7 7 0 0 0 10 10',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 11v6 M12 7h.01',lock:'M5 10h14v12H5z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',trash:'M3 6h18 M9 6V3h6v3 M6 6v15h12V6 M10 10v7 M14 10v7',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 m5 12 6 6',leaf:'M20 3C9 3 3 8 5 15s14 6 15-12 M4 21 15 10',code:'m8 6-6 6 6 6 M16 6l6 6-6 6 M14 3l-4 18',heart:'M12 21S2 14 2 8a5 5 0 0 1 10-1 5 5 0 0 1 10 1c0 6-10 13-10 13',headphones:'M3 14v-3a9 9 0 0 1 18 0v3 M3 12h4v9H3z M17 12h4v9h-4z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const btn=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const link=(label,route,cls='')=>`<a href="#${route}" class="btn ${cls}">${label}</a>`;
const actionLink=(label,action,attrs='')=>`<button class="text-btn" data-action="${action}" ${attrs}>${label}</button>`;
const initials=name=>String(name).trim().split(/\s+/u).slice(0,2).map(n=>[...n][0]).join('').toUpperCase();
const person=id=>state.members.find(m=>m.id===id)||{name:id==='self'?state.self.name:'Former member',color:'sage',id};
const avatar=(m,cls='')=>`<span class="avatar ${m.color||'sage'} ${cls}">${escape(initials(m.name))}</span>`;
const pill=(label,cls='')=>`<span class="pill ${cls}">${label}</span>`;
const time=t=>new Date(t).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',hour12:false});
const age=t=>{const n=Math.max(0,Math.floor((Date.now()-t)/1000));return n<60?`${n}s ago`:n<3600?`${Math.floor(n/60)}m ago`:`${Math.floor(n/3600)}h ago`;};
const isFresh=p=>p&&Date.now()-p.time<=60000;
const info=(key,value)=>`<div class="info-row"><dt>${key}</dt><dd>${value}</dd></div>`;
const note=(text,cls='')=>`<div class="note ${cls}">${text}</div>`;
const progress=(value,label='Preparing')=>`<div class="progress"><span style="width:${value}%"></span></div><div class="progress-label"><span>${label}</span><span>${value}%</span></div>`;
const field=(label,name,value='',type='text',extra='')=>`<div class="form-field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${escape(value)}" type="${type}" ${extra}></div>`;
const select=(label,name,options,value)=>`<div class="form-field"><label for="${name}">${label}</label><select name="${name}" id="${name}">${options.map(o=>{const v=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<option value="${escape(v)}" ${String(v)===String(value)?'selected':''}>${escape(l)}</option>`}).join('')}</select></div>`;
const check=(label,name,checked=false,help='')=>`<label class="check-row"><input type="checkbox" name="${name}" ${checked?'checked':''}><span>${label}${help?`<small>${help}</small>`:''}</span></label>`;
const toggle=(label,description,action,on)=>`<div class="toggle-row"><div><b>${label}</b><small>${description}</small></div><button class="toggle ${on?'on':''}" role="switch" aria-checked="${on}" aria-label="${label}" data-action="${action}"></button></div>`;
const empty=(title,description,cta='')=>`<div class="empty"><div class="status-icon">${icon('leaf')}</div><h3>${title}</h3><p>${description}</p>${cta}</div>`;
const owner=()=>state.group?.owner==='self';
function route(){return location.hash.slice(1).split('?')[0]||(fresh?'onboarding':'field');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function persist(){if(showcase)return true;try{localStorage.setItem(storageKey,JSON.stringify(state));storageAvailable=true;return true;}catch{storageAvailable=false;return false;}}
function dispatch(action,p={},render=true){try{const next=transition(state,action,p);if(action==='draft'&&!storageAvailable){next.draft.state='error';}state=next;if(!persist()){if(action==='draft')state.draft.state='error';if(action==='preferences')toast('Device storage is unavailable; reload before changing preferences.');}if(render)renderApp();if(state.notice)toast(state.notice);return true;}catch(error){toast(error.message);const inline=$('.error-text');if(inline)inline.textContent=error.message;return false;}}
function header(title,subtitle,eyebrow='YOUR FIELD NETWORK',actions=''){return `<header class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p class="subtitle">${subtitle}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</header>`;}
function back(title='Field kit',to='kit'){return `<a class="back-link" href="#${to}">${icon('back')}${title}</a>`;}
function footer(){return `<footer class="footnote"><span><i class="badge-dot"></i>Independent design experiment · fictional people & simulated connections</span><a href="#roadmap">Built for the field. Honest about the limits. ${icon('arrow','sm').replace('class="icon sm"','class="icon sm" style="display:inline;width:11px;height:11px;vertical-align:middle"')}</a></footer>`;}
const mainNav=[['field','field','Field'],['chat','chat','Conversation'],['map','map','Map'],['people','people','People'],['kit','kit','Field kit']];
function renderApp(){
 const focus=document.activeElement?.id,selection=document.activeElement?.selectionStart;
 const r=route(),primary=['voice','chat'].includes(r)?'chat':['people','nodes'].includes(r)?'people':['map','offline'].includes(r)?'map':['field','onboarding'].includes(r)?'field':'kit';
 document.body.classList.toggle('lowlight',state.preferences.appearance==='lowlight');
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#field"><span class="brand-mark"></span>AuMaNET</a><div class="brand-sub">A little closer, out there.</div><nav class="side-nav" aria-label="Primary navigation">${mainNav.map(([key,i,label])=>`<a class="nav-item ${primary===key?'active':''}" href="#${key}" ${primary===key?'aria-current="page"':''}>${icon(i)}${label}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-item ${r==='settings'?'active':''}" href="#settings">${icon('settings')}Preferences</a><div class="field-note"><span class="tiny-tag">CONNECTED BY CHOICE</span><p>Your group stays local.<br>Your privacy stays yours.</p><a class="text-btn" href="#connection">Connection details ${icon('arrow','sm')}</a></div><button class="profile-mini" data-action="identity" style="background:none;border:0;padding:0;text-align:left">${avatar({...state.self,color:'sage'})}<span><b>${escape(state.self.name)}</b><small>${owner()?'Group owner':'Your phone'}</small></span></button></div></aside><main class="main"><div class="topbar"><div class="breadcrumb">${icon('leaf','sm')}<span>${escape(state.group?.name||'Your next adventure')}</span><span>/</span><span>${({field:'Overview',chat:'Conversation',map:'The local map',people:'Your people',nodes:'Radio nodes',kit:'Field kit'})[r]||r.replace(/([A-Z])/g,' $1')}</span></div><div class="top-right"><span class="date">WEDNESDAY, 18 NOVEMBER</span><a href="#connection"><i class="status-dot ${state.connection.group?'':'off'}"></i>${state.connection.group?'Group connected':'Saved locally'}</a><button class="icon-button" data-action="activeServices" aria-label="Active services">${icon('bell','sm')}</button></div></div><div class="mobile-top"><a class="brand" href="#field"><span class="brand-mark"></span>AuMaNET</a><div class="mobile-status"><a href="#connection"><i class="status-dot ${state.connection.group?'':'off'}"></i>${state.connection.group?'Connected':'Offline'}</a><button data-action="identity" aria-label="Your profile" style="background:none;border:0;padding:0">${avatar({...state.self,color:'sage'})}</button></div></div>${page(r)}${footer()}</main><nav class="bottom-nav" aria-label="Mobile navigation">${mainNav.map(([key,i,label])=>`<a href="#${key}" class="${primary===key?'active':''}" ${primary===key?'aria-current="page"':''}>${icon(i)}<span>${key==='chat'?'Talk':key==='kit'?'Kit':label}</span></a>`).join('')}</nav>${state.voice.joined&&r!=='voice'?`<div class="voice-persist"><a href="#voice">${icon('mic','sm').replace('class="icon sm"','class="icon sm" style="display:inline;vertical-align:middle;margin-right:7px"')}Voice joined · ${state.voice.muted?'mic muted':state.voice.holding?'transmitting':'mic enabled'}</a>${actionLink('Mute','mute')}${actionLink('Leave','leaveVoice')}</div>`:''}</div>`;
 if(focus){const el=document.getElementById(focus);if(el){el.focus({preventScroll:true});if(typeof selection==='number'&&el.setSelectionRange)try{el.setSelectionRange(selection,selection);}catch{}}}
 wireMaps();wireHold();
}
function page(r){return ({field:fieldPage,chat:chatPage,map:mapPage,people:peoplePage,nodes:nodesPage,kit:kitPage,voice:voicePage,connection:connectionPage,offline:offlinePage,internet:internetPage,firmware:firmwarePage,radio:radioPage,measurements:measurementsPage,planner:plannerPage,settings:settingsPage,diagnostics:diagnosticsPage,onboarding:onboardingPage,join:joinPage,operator:operatorPage,roadmap:roadmapPage})[r]?.()||fieldPage();}
function mapMarkup(full=false){const markers=state.members.filter(m=>m.id!=='self'&&m.position).map(m=>`<button class="map-marker ${!isFresh(m.position)||!m.connected?'stale':''}" style="left:${m.position.x}%;top:${m.position.y}%" data-action="member" data-id="${m.id}" aria-label="Inspect ${escape(m.name)} position">${avatar(m)}<span class="label">${escape(m.name.split(' ')[0])}${!isFresh(m.position)?' · last known':''}</span></button>`).join('');return `<div class="map-surface" data-map><div class="sr-only">Representative fictional area, with roads, trails, creek, contours and group locations. Use zoom buttons or drag to explore.</div>${terrainSVG()}<div class="map-markers">${markers}${state.location.fix?`<button class="map-marker self" style="left:${state.location.fix.x}%;top:${state.location.fix.y}%" data-action="location" aria-label="Your position">${avatar({...state.self,color:'sage'})}<span class="label">You · ${state.location.sharing?'sharing':'private'}</span></button>`:''}</div></div>${full?`<div class="map-toolbar"><button class="map-search" data-action="coordinates">${icon('search')}Fern Ridge & Willow Creek ${icon('down','sm')}</button>${link(`${icon('download','sm')} Offline areas`,'offline','secondary small')}</div>`:`<div class="map-top"><span class="pill"><i class="status-dot"></i>Saved map · available offline</span><a href="#map" class="icon-button" style="pointer-events:auto;background:#fffef8;border:0" aria-label="Open map">${icon('arrow','sm')}</a></div>`}<div class="map-controls"><button class="icon-button" data-action="zoomIn" aria-label="Zoom in">${icon('plus','sm')}</button><button class="icon-button" data-action="zoomOut" aria-label="Zoom out">${icon('minus','sm')}</button><button class="icon-button" data-action="focusGroup" aria-label="Fit fresh group positions">${icon('people','sm')}</button>${full?`<button class="icon-button" data-action="locateMap" aria-label="Find my own position">${icon('target','sm')}</button>`:''}</div><span class="map-caption">Representative geography · original schematic artwork</span>`;}
function fieldPage(){if(!state.group)return onboardingPage();const peers=state.members.filter(m=>m.id!=='self'&&m.connected),voicePeers=peers.filter(m=>m.voice);return `${header('Out here.<br>Still together.',`A little signal. A familiar voice. Your group, within reach.`,'YOUR GROUP · '+escape(state.group.name),`<div class="avatar-stack">${state.members.map(m=>avatar(m)).join('')}</div>${link(`${icon('people','sm')} Your group`,'people','secondary')}`)}<div class="dashboard"><div class="field-main"><section class="card map-card"><div style="position:relative;height:375px" class="field-map-inner">${mapMarkup()}</div><div class="map-bottom"><div><b>Somewhere worth staying connected.</b><small>${state.members.filter(m=>m.position&&isFresh(m.position)).length} fresh positions · ${state.areas.filter(a=>a.status==='ready').length} saved area${state.areas.filter(a=>a.status==='ready').length===1?'':'s'}</small></div>${link('Explore map '+icon('arrow','sm'),'map','secondary small')}</div></section><section class="card mini-conversation"><div class="card-head"><h3>${icon('chat','sm')} Around the group</h3><a class="text-btn" href="#chat">Open conversation ${icon('arrow','sm')}</a></div>${state.messages.slice(-2).map(m=>`<div class="chat-line">${avatar(person(m.sender))}<div class="text"><strong>${escape(person(m.sender).name.split(' ')[0])}</strong><time>${time(m.time)}</time><p>${escape(m.text)}</p></div></div>`).join('')||'<p style="font-size:12px">Your first shared thought starts here.</p>'}<a href="#chat" class="preview-compose"><span>Leave a message for everyone…</span><span class="icon-button">${icon('arrow','sm')}</span></a></section></div><aside class="field-aside"><section class="card network-card"><div class="link-line"><span class="section-label">THE GROUP CONNECTION</span>${pill(state.connection.group?'LIVE & LOCAL':'SAVED OFFLINE','dark')}</div><h2>${state.connection.group?'You’re in good company.':'Your group is still yours.'}</h2><p style="font-size:11px">${state.connection.group?'Your phone and node are connected. No internet needed.':'Reconnect when your node is nearby. Your messages are saved.'}</p><div class="network-stats"><div><b>${state.members.filter(m=>m.connected).length}<span style="font-family:Arial;font-size:12px;color:#a8c29a"> / ${state.members.length}</span></b><small>PHONES CONNECTED</small></div><div><b>${state.nodes.filter(n=>n.verified).length}</b><small>CHECKED NODES</small></div><div><b>${state.connection.radio?'Local':'—'}</b><small>RADIO REACHABILITY</small></div></div><a href="#connection" class="text-btn">${state.connection.group?'Everything in its own state':'Review your connection'} ${icon('arrow','sm')}</a></section><section class="card voice-preview"><div class="card-head"><h3>A voice goes further.</h3><span class="waves">${[9,18,27,16,23,12,20].map(h=>`<i style="--h:${h}px"></i>`).join('')}</span></div><p>${voicePeers.length?`${voicePeers.map(m=>m.name.split(' ')[0]).join(' and ')} are on the voice channel.`:'Voice is quiet for now.'}<br>You decide when your microphone is heard.</p><div class="voice-foot"><div class="avatar-stack">${voicePeers.map(m=>avatar(m)).join('')}</div>${link(state.voice.joined?'Open voice '+icon('arrow','sm'):'Join the conversation '+icon('mic','sm'),'voice','small')}</div></section><section class="card"><div class="card-head"><h3>Your choices, at a glance</h3>${icon('shield','sm')}</div>${privacyRows()}<div class="divider" style="margin:17px 0"></div><a class="text-btn" href="#settings">Privacy & preferences ${icon('arrow','sm')}</a></section></aside></div>`;}
function privacyRows(){return `<div class="mini-row"><div class="status-icon">${icon(state.voice.muted?'muted':'mic','sm')}</div><div class="row-body"><b>Microphone</b><small>${state.voice.joined?'Voice joined · transmission controlled':'Not joined · no microphone access'}</small></div><span class="pill ${state.voice.muted?'gray':''}">${state.voice.muted?'Muted':'Enabled'}</span></div><div class="mini-row"><div class="status-icon">${icon('location','sm')}</div><div class="row-body"><b>Your position</b><small>${state.location.sharing?'Publishing to this verified group':'Kept to yourself'}</small></div><span class="pill ${state.location.sharing?'':'gray'}">${state.location.sharing?'Sharing':'Private'}</span></div><div class="mini-row"><div class="status-icon">${icon('globe','sm')}</div><div class="row-body"><b>Mobile data</b><small>${state.internet.offer?'Voluntarily offered to your group':'Sharing is always your choice'}</small></div><span class="pill ${state.internet.offer?'':'gray'}">${state.internet.offer?'Offering':'Not shared'}</span></div>`;}
function chatPage(){if(!state.group)return onboardingPage();return `${header('A thread to stay close.','Saved on your phone, even when the signal takes a break.','CONVERSATION · '+escape(state.group.name),link(icon('mic','sm')+' Voice','voice','secondary'))}<div class="split-layout"><section class="card conversation-card"><div class="conversation-top"><div><h3>${escape(state.group.name)}</h3><small>${state.members.length} approved phones · ${escape(state.sync)}</small></div><button class="icon-button" data-action="conversationOptions" aria-label="Conversation options">${icon('more')}</button></div><div class="message-list"><div class="date-divider">TODAY · 18 NOVEMBER</div>${state.messages.map(messageMarkup).join('')||empty('Say something worth keeping.','Messages stay with this group. A receipt means stored on a device, never read by a person.')}</div><form class="compose" id="compose-form"><div class="compose-box"><button type="button" class="icon-button" data-action="choosePhoto" aria-label="Attach JPEG or PNG">${icon('plus')}</button><textarea name="message" id="draft-text" placeholder="A message for everyone…" aria-label="Message draft" rows="1">${escape(state.draft.text)}</textarea><button class="icon-button send" aria-label="Send message" type="submit">${icon('send','sm')}</button></div><div class="compose-meta"><span id="draft-status">${state.draft.state==='saved'?'Draft saved on this phone':state.draft.state==='error'?'Draft not saved · retry from options':'Saving…'}</span><span id="draft-bytes">${bytes(state.draft.text)} / 2,048 bytes</span></div></form></section><aside class="stack"><section class="card"><div class="card-head"><h3>In this conversation</h3>${pill(`${state.members.length} / 5`,'outline')}</div>${state.members.map(m=>`<button class="mini-row" data-action="member" data-id="${m.id}" style="border-left:0;border-right:0;border-top:0;background:none;width:100%;text-align:left">${avatar(m)}<div class="row-body"><b>${escape(m.name)}${m.id==='self'?' · you':''}</b><small>${m.connected?'Connected to group':'Approved · disconnected'}</small></div><i class="status-dot ${m.connected?'':'off'}"></i></button>`).join('')}</section><section class="card"><div class="card-head"><h3>${icon('lock','sm')} A private thread</h3></div><p style="font-size:11px;line-height:1.8">Messages are for their original recipients. You can keep talking locally without an internet connection.</p><div class="divider"></div>${note('A delivery mark means the other phone stored your message. It never tells you whether someone read it.')}<div style="margin-top:17px">${actionLink('History & delivery details','conversationOptions')}</div></section></aside></div>`;}
function messageMarkup(m){const me=m.sender==='self',p=person(m.sender),status={received:'Saved on your phone',partial:`${m.acks.length} of ${m.recipients.length} phones stored`,stored:'Stored by recipient devices',queued:'Queued · not attempted',uncertain:'Outcome unknown · check before retrying',cancelled:'Further attempts stopped',expired:'Delivery window expired'}[m.state];return `<article class="message ${me?'self':''}">${avatar(p)}<div style="min-width:0"><button class="bubble" data-action="${m.photo?'photo':'message'}" data-id="${m.id}">${!me?`<span class="sender">${escape(p.name.split(' ')[0])}</span>`:''}${m.photo?m.photo.state==='available'?`<div class="photo-thumb">${m.photo.source==='illustration'?creekSVG():`<img src="${escape(m.photo.source)}" alt="Prepared group photo">`}</div>`:`<div class="photo-pending">${icon('photo')}<p>Photo announced · ${m.photo.state}</p>${progress(m.photo.progress,'Photo bytes')}</div>`:''}<p>${escape(m.text)}</p></button><div class="message-meta"><span>${time(m.time)}</span>${me?icon(m.state==='stored'?'double':'check','sm'):''}<span>${status}</span>${m.context?.position?icon('location','sm'):''}</div></div></article>`;}
function mapPage(){return `${header('Everyone has a place.','Find your bearings. Share your position only when you choose.','THE LOCAL MAP',btn(icon('location','sm')+' Your position','location','secondary'))}<section class="map-full">${mapMarkup(true)}<div class="map-person-tray">${state.members.filter(m=>m.position).map(m=>`<button class="person-chip" data-action="focusMember" data-id="${m.id}">${avatar(m)}<span><b>${escape(m.name.split(' ')[0])}</b><small>${isFresh(m.position)&&m.connected?'Fresh':'Last known'} · ±${m.position.accuracy} m</small></span></button>`).join('')}</div></section><div class="map-below"><section class="card"><div class="card-head"><h3>${icon('location','sm')} Your position, your decision</h3>${pill(state.location.sharing?'Sharing':'Private',state.location.sharing?'':'gray')}</div><p style="font-size:11px;line-height:1.75">${state.location.fix?`${state.location.fix.lat.toFixed(5)}, ${state.location.fix.lng.toFixed(5)} · ±${state.location.fix.accuracy} m · ${age(state.location.fix.time)}. ${isFresh(state.location.fix)&&state.location.acquiring?'Foreground fix.':'Last known observation.'}`:'Explore this map without a position fix. Finding yourself does not share your position with anyone.'}</p><div style="margin-top:16px;display:flex;gap:9px;flex-wrap:wrap">${btn(state.location.fix?'Manage position':'Find my position',state.location.fix?'location':'locate','small')}${state.location.fix&&state.location.acquiring?btn('Follow my position','follow','secondary small'):''}${btn('Inspect coordinates','coordinates','secondary small')}</div></section><section class="card"><div class="card-head"><h3>${icon('download','sm')} A map that comes along</h3>${pill(`${state.areas.filter(a=>a.status==='ready').length} saved`,'outline')}</div><p style="font-size:11px;line-height:1.75">Fern Ridge’s local roads, tracks and contours are bundled in this prototype. Saved areas are used automatically when internet is unavailable.</p><div style="margin-top:16px">${link('Manage offline areas '+icon('arrow','sm'),'offline','secondary small')}</div></section></div>`;}
function peoplePage(){if(!state.group)return onboardingPage();return `${header('Your small, trusted circle.','A familiar name is useful. A checked phone identity is what belongs to the group.','PEOPLE · '+escape(state.group.name),owner()?btn(icon('plus','sm')+' Invite someone','invitation','secondary'):'')}<nav class="subnav"><a href="#people" class="active">People · ${state.members.length}</a><a href="#nodes">Radio nodes · ${state.nodes.length}</a></nav><div class="split-layout"><div class="stack">${state.requests.length?`<section class="card"><div class="card-head"><h3>Waiting at the door</h3>${pill(`${state.requests.length} request`,'amber')}</div>${state.requests.map(r=>`<div class="mini-row">${avatar({...r,color:'blue'})}<div class="row-body"><b>${escape(r.name)}</b><small>Compare identity · expires ${time(r.expires)}</small></div>${btn('Review','reviewRequest','secondary small',`data-id="${r.id}"`)}</div>`).join('')}</section>`:''}<div class="member-grid">${state.members.map(m=>`<button class="member-card" data-action="member" data-id="${m.id}"><div class="head">${avatar(m,'large')}<div><h3>${escape(m.name)}${m.id==='self'?' <span style="font-size:10px;color:var(--muted)">you</span>':''}</h3><small>${m.id===state.group.owner?'Group owner':'Approved member'} · ${m.connected?'connected':'away'}</small></div></div><div class="facts"><span>${icon(m.voice?'mic':'muted','sm')}${m.id==='self'?(state.voice.joined?'On voice':'Voice off'):m.voice&&m.connected?'On voice':'Voice off'}</span><span>${icon('location','sm')}${m.position?(isFresh(m.position)&&m.connected?'Fresh position':'Last known'):'Position private'}</span>${icon('arrow','sm')}</div></button>`).join('')}</div></div><aside class="stack"><section class="card"><div class="card-head"><h3>About this group</h3>${icon('shield','sm')}</div><dl class="info-list">${info('Group name',escape(state.group.name))}${info('Owner',escape(person(state.group.owner).name))}${info('Approved phones',`${state.members.length} of 5`)}${info('Membership revision',state.group.revision)}${info('Future history sharing',state.group.historyFuture?'Enabled':'Original recipients only')}</dl><div class="divider"></div><p style="font-size:11px;line-height:1.8">Being away doesn’t remove someone from the group. Voice, position and internet sharing each have their own consent.</p>${owner()?`<div style="margin-top:18px">${actionLink('Group settings','groupSettings')}</div>`:''}</section><section class="card"><span class="section-label">OFFLINE, TOGETHER</span><h2 style="font-size:25px;margin:13px 0 10px">A new node, beyond reach?</h2><p style="font-size:11px;line-height:1.8">Exchange a membership request and approval without a live radio connection. Node provisioning is a separate, trusted USB step.</p><div style="margin-top:17px">${actionLink('Offline membership exchange','offlineMembership')}</div></section></aside></div>`;}
function nodesPage(){return `${header('The quiet connection.','Phones carry people. Nodes carry radio. These are separate identities and observations.','RADIO NODES',link(icon('people','sm')+' People','people','secondary'))}<nav class="subnav"><a href="#people">People · ${state.members.length}</a><a href="#nodes" class="active">Radio nodes · ${state.nodes.length}</a></nav><div class="grid two">${state.nodes.map(n=>`<section class="card"><div class="card-head"><h3>${icon('node')} ${escape(n.name)}</h3>${pill(n.verified?'Checked association':'Unknown',n.verified?'':'amber')}</div><div class="node-diagram"><div class="node-unit">${icon('node')}</div><div style="padding-left:20px"><span class="section-label">${escape(n.serial)}</span><h2 style="font-size:28px;margin:8px 0">${escape(person(n.phone).name.split(' ')[0])}’s field node</h2><small>Association checked · attachment is observed separately</small></div></div><dl class="info-list">${info('Installed firmware',n.firmware)}${info('Build evidence',escape(n.build))}${info('Current radio',`Channel ${n.channel} · ${n.frequency} MHz · ${n.width} MHz`)}${info('Boot health',n.health)}${info('Battery level','Not reported')}${info('Live Wi-Fi attachment',n.phone==='self'?(state.connection.node?'Verified locally':'Unavailable'):'Not observable remotely')}</dl><div class="divider"></div><div class="link-line">${btn('Inspect identity','node','secondary small',`data-id="${n.id}"`)}<a href="#firmware" class="text-btn">Firmware ${icon('arrow','sm')}</a></div></section>`).join('')||`<section class="card">${empty('No checked nodes yet.','Saved phone membership is independent of node provisioning.',link('Review setup','connection'))}</section>`}</div><section class="card" style="margin-top:20px"><div class="card-head"><h3>One observation, one direction</h3>${pill('SIMULATED','outline')}</div><div class="grid two"><div><div class="node-diagram"><div><div class="node-unit">${icon('phone')}</div><small style="display:block;text-align:center;margin-top:8px">You</small></div><div class="node-line"></div><div><div class="node-unit">${icon('phone')}</div><small style="display:block;text-align:center;margin-top:8px">Mara</small></div></div></div><div><dl class="info-list">${info('Received signal','−67 dBm · Mara → your node')}${info('Reporting node','FR-81A2-00C9')}${info('Verification','Associated phone pair checked')}${info('Original RF sample age','Unavailable · cached report')}${info('Reverse direction','Unsupported observation')}</dl><p style="font-size:10px;margin-top:15px">This is a historical synthetic signal report, not a current range or direct-path guarantee. GPS distance does not determine radio quality.</p></div></div></section>`;}
function kitPage(){const tiles=[['connection','wifi','Connection','Your saved group, node and safe recovery choices.',state.connection.status],['internet','globe','Shared internet','Give a little data, or choose a trusted provider.',state.internet.receive?'Using Mara':'Optional'],['firmware','node','Node care','Check exact firmware. Prepare first, install separately.',`${state.nodes[0]?.firmware||'Unknown'} installed`],['radio','radio','Radio settings','A checked two-node link, with a way back.',`Channel ${state.nodes[0]?.channel||'unknown'}`],['measurements','test','Connection tests','Measure a moment. Keep the conditions with it.','Permission required'],['planner','leaf','Capacity planner','Explore what your group might ask of a link.','Planning only'],['offline','download','Offline areas','Bring the map along. Keep the places you need.',`${state.areas.length} saved area`],['settings','settings','Preferences','Settle into your own units, light and alerts.','On this phone'],['diagnostics','shield','Diagnostics','A useful status report, with private details left out.','Review before export']];return `${header('A little preparation.<br>A better day out.','Connection tools and thoughtful controls, ready when you need them.','YOUR FIELD KIT')}<div class="kit-grid">${tiles.map(([r,i,title,description,status])=>`<a href="#${r}" class="kit-card"><div class="top"><div class="status-icon">${icon(i)}</div>${pill(status,'outline')}${icon('arrow','arrow sm')}</div><h3>${title}</h3><p>${description}</p></a>`).join('')}</div><div class="wide-banner"><div><span class="section-label">FOR THE CURIOUS</span><h3 style="margin-top:8px">A clear line between now and next.</h3><p>This experiment shows choices and consequences. Real-world range, audio quality and physical acceptance need real evidence.</p></div>${link('What’s planned '+icon('arrow','sm'),'roadmap','secondary')}</div>`;}
function voicePage(){const v=state.voice,peers=state.members.filter(m=>m.id!=='self'&&m.voice&&m.connected);return `${header('Some things are better said.','Join quietly. Listen in. Speak when you mean to.','GROUP VOICE',link(icon('chat','sm')+' Messages','chat','secondary'))}<div class="split-layout"><div class="stack"><section class="voice-stage"><div class="link-line"><span class="section-label">${escape(state.group?.name||'No group')} · LOCAL VOICE</span>${pill(v.joined?'JOINED':'NOT JOINED','dark')}</div><div class="rings"></div><div class="voice-people">${peers.slice(0,2).map(m=>`<div class="voice-person"><div class="voice-ring">${avatar(m)}</div><b>${escape(m.name.split(' ')[0])}</b><small>Connected · listening</small></div>`).join('')}<div class="voice-person you">${avatar({...state.self,color:'sage'})}<b>You</b><small>${!v.joined?'Not joined':v.muted?'Microphone muted':v.holding?'Transmitting':v.mode==='handsfree'?'Listening locally':'Ready for a new hold'}</small></div></div><div class="voice-status">${!v.joined?'Come as you are.':v.holding?'You’re being heard.':v.muted?'Here, and quietly listening.':v.mode==='handsfree'?'Listening for speech.':'Your voice, on your terms.'}</div><p>${!v.joined?'Your microphone stays off until you join.':v.muted?'Unmute deliberately before you speak.':v.mode==='handsfree'?'Local speech detection may also hear nearby voices or noise.':'A fresh press and hold transmits. Releasing stops.'}</p><div class="voice-actions">${v.joined?`<button class="icon-button ${v.muted?'muted':''}" data-action="${v.muted?'unmute':'mute'}" aria-label="${v.muted?'Enable microphone':'Mute microphone'}">${icon(v.muted?'muted':'mic')}</button>${v.mode==='hold'?`<button class="talk-button ${v.holding?'talking':''}" id="hold-talk" ${v.muted?'disabled':''}>${icon('mic','sm')}${v.holding?'Transmitting…':'Hold to talk'}</button>`:`<button class="talk-button" data-action="${v.muted?'unmute':'mute'}">${icon(v.muted?'mic':'muted','sm')}${v.muted?'Enable hands-free':'Mute hands-free'}</button>`}<button class="icon-button" data-action="receiveAudio" aria-label="${v.receive?'Suppress received audio':'Restore received audio'}">${icon(v.receive?'volume':'volumeOff')}</button>`:btn(icon('headphones')+' Join voice, muted','joinVoice','lime')}</div>${v.joined?`<div style="text-align:center;margin-top:17px"><button class="text-btn" style="color:#d3e0c5;font-size:10px" data-action="leaveVoice">Leave voice session</button></div>`:''}</section><section class="card"><div class="card-head"><h3>${icon('shield','sm')} A microphone with clear boundaries</h3></div><p style="font-size:11px;line-height:1.9">Joining may give the session microphone access, even while the transmission gate is muted. In this browser experiment, no microphone is opened. A new hold, route change, interruption or release always follows the mute rules. Voices can overlap; there is no single-speaker floor.</p>${v.status.includes('Interrupted')?`<div style="margin-top:15px">${note(v.status,'amber')}${btn('Recover voice, muted','recoverVoice','small')}</div>`:''}</section></div><aside class="stack"><section class="card"><div class="card-head"><h3>Make yourself comfortable</h3>${icon('settings','sm')}</div><form id="voice-settings">${select('Input mode','mode',[['hold','Press and hold'],['handsfree','Hands-free speech activation']],v.mode)}${select('Audio output','output',[['phone','This phone'],['wired','Wired / USB audio (simulated)'],['bluetooth','Saved Bluetooth headset · unavailable']],v.output)}${select('Speech sensitivity','sensitivity',[['quiet','Quiet speech · more false activation'],['balanced','Balanced'],['strong','Strong speech · may miss quiet voices']],v.sensitivity)}${note('Changing a mode, output or sensitivity always re-mutes. Basic speech detection cannot identify who you intended to hear.')}<div class="error-text"></div><div style="display:flex;gap:8px;margin-top:17px"><button class="btn small" type="submit">Apply & mute</button><button class="btn secondary small" type="reset">Discard edits</button></div></form><div class="divider"></div><dl class="info-list">${info('Actual output',v.actualOutput==='phone'?'This phone':'Wired / USB · simulated')}${info('Received audio',v.receive?'On':'Suppressed · mic muted')}${info('Speech detector',v.detector?'Available · simulated':'Unavailable · use hold')}</dl></section></aside></div>`;}
function connectionPage(){const c=state.connection,t=c.trusted;return `${back()}${header('A connection you can trust.','A wireless signal is a beginning. Identity and group checks come next.','CONNECTION',btn(icon('refresh','sm')+' Recheck','recheckConnection','secondary'))}<div class="split-layout"><div class="stack"><section class="card"><div class="card-head"><h3>Six separate answers</h3>${pill(c.status,c.group?'':'amber')}</div><div class="status-list">${[['wifi','Phone Wi-Fi',c.wifi?'Available · local network':'Unavailable',c.wifi],['node','Your node',c.node?'Identity checked · FR-81A2-00C9':'Node attachment not verified',c.node],['people','Approved group',c.group?`${escape(state.group?.name)} · membership verified`:'Saved membership is not a live connection',c.group],['radio','Radio reachability',c.radio?'Supported two-node link observed':'No current radio observation',c.radio],['chat','Message transfers',c.transfer?'Ready · delivery confirmed per message':'Paused or unavailable',c.transfer],['globe','Usable internet',c.internet||state.internet.receive?'Personal / chosen shared connection':'Not required for the local group',c.internet||state.internet.receive]].map(([i,label,desc,on])=>`<div class="status-item"><div class="status-icon ${on?'':'off'}">${icon(i,'sm')}</div><div class="body"><b>${label}</b><small>${desc}</small></div>${pill(on?'Available':'Separate / off',on?'':'gray')}</div>`).join('')}</div></section><section class="card"><div class="card-head"><h3>Your next connection</h3>${icon('shield','sm')}</div>${!state.group?empty('Start with your people.','Create a private group or use an invitation.',link('Set up a group','onboarding')):!c.provisioned?`${note('Membership is saved. Your radio node still needs trusted external USB provisioning. The prototype can acknowledge a simulated external completion.','amber')}<ol class="step-list"><li><span class="step-number">1</span><div><b>Keep this phone identity</b><small>${escape(state.self.identity)}</small></div></li><li><span class="step-number">2</span><div><b>Use the approved external USB process</b><small>Preserve identities, keys, memberships and histories.</small></div></li><li><span class="step-number">3</span><div><b>Verify the provisioned node</b><small>Do not infer setup from a Wi-Fi connection.</small></div></li></ol>${btn('Check simulated external setup','provision','small')}`:`${c.stage?`<ol class="step-list">${['Join the saved node','Verify identity & group configuration','Recover eligible recent messages'].map((x,i)=>`<li class="${c.stage===i+1?'active':c.stage>i+1?'done':''}"><span class="step-number">${c.stage>i+1?'✓':i+1}</span><b>${x}</b></li>`).join('')}</ol>${btn('Cancel connection','disconnect','secondary small')}`:`<p style="font-size:12px;line-height:1.8">${c.group?'Your group is verified. You can remember a precise, consented connection choice for a bounded two-hour run.':'Rejoin your saved membership with voice and position publication off. Or resume your reviewed trusted choice.'}</p><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:19px">${!c.group?btn('Rejoin saved membership','rejoin','small'):''}${btn(t?'Review saved choice':'Remember this connection','trusted','secondary small')}${t&&!c.run?btn('Resume trusted run','resume','small'):''}${c.group||c.run?btn('Disconnect safely','disconnectConfirm','danger small'):''}${!c.group?btn('Use a recovery code','useRecovery','secondary small'):''}</div>`}`}</section></div><aside class="stack"><section class="card"><div class="card-head"><h3>${icon('lock','sm')} Saved, not forgotten</h3></div><dl class="info-list">${info('Phone identity',escape(state.self.identity.slice(0,23))+'…')}${info('Membership',state.group?'Approved & saved':'Not established')}${info('Trusted choice',t?`${escape(state.group?.name)} · exact node`:'Not yet remembered')}${info('Automatic recovery',c.run?'Active · at most 2 hours':'Off')}${info('Voice on recovery',t?t.voice==='off'?'Off':t.voice==='muted'?'Joined muted':'Fresh hold only':'Not selected')}${info('Position on recovery',t?.location?'Separately authorized':'Not shared')}</dl>${t?`<div class="divider"></div>${actionLink('Forget saved connection choice','forgetConfirm')}`:''}</section>${owner()?`<section class="card"><span class="section-label">BRING YOUR GROUP BACK</span><h2 style="font-size:25px;margin:12px 0">A recovery code.</h2><p style="font-size:11px;line-height:1.8">Help already-approved phones find you again. A recovery code cannot admit a new member.</p><div style="margin-top:17px">${btn('Create recovery code','recoveryCode','secondary small')}</div></section>`:''}</aside></div>`;}
function offlinePage(){return `${back('Map','map')}${header('Take a little of the world.','Prepare an area while internet is available. It will be there when it isn’t.','OFFLINE AREAS',btn(icon('plus','sm')+' Add an area','newArea','secondary'))}<div class="split-layout"><div class="stack">${state.areas.map(a=>`<section class="card"><div class="card-head"><div><span class="section-label">${a.status==='ready'?'AVAILABLE OFFLINE':'INCOMPLETE · NOT YET USABLE'}</span><h2 style="font-size:28px;margin-top:8px">${escape(a.name)}</h2></div><div class="status-icon">${icon(a.status==='ready'?'map':'download')}</div></div><div style="height:150px;position:relative;overflow:hidden;border-radius:12px;margin-bottom:20px;background:#e6eadb">${terrainSVG()}</div><dl class="info-list">${info('Coverage',`${a.extent} × ${a.extent} km · ${a.lat.toFixed(4)}, ${a.lng.toFixed(4)}`)}${info('Size & detail',`${a.size.toFixed(1)} MiB · ${a.terrain?'terrain & contours':'roads & tracks'}`)}${info('Data date',a.date)}${info('Files',a.files.toLocaleString())}${info('State',a.status)}</dl>${a.status!=='ready'?progress(a.progress,a.status==='verifying'?'Verifying files':a.status==='labels'?'Preparing labels':`${Math.round(a.size*a.progress/100)} / ${a.size.toFixed(1)} MiB`):''}<div class="divider"></div><div class="link-line"><div style="display:flex;gap:9px">${a.status==='ready'?link('Explore this area','map','secondary small'):['interrupted','failed'].includes(a.status)?btn('Retry download','retryArea','small',`data-id="${a.id}"`):btn('Pause download','pauseArea','secondary small',`data-id="${a.id}"`)}</div>${actionLink('Remove','removeAreaConfirm',`data-id="${a.id}"`)}</div></section>`).join('')}</div><aside class="stack"><section class="card"><div class="card-head"><h3>Room for the essentials</h3>${icon('download','sm')}</div><div class="large-stat">${state.areas.length}<span>/ 4 areas</span></div><p style="font-size:11px;line-height:1.8;margin-top:13px">Up to 256 MiB per area. Incomplete downloads stay separate until labels and files are verified. Retry can start the download again.</p><div class="divider"></div>${note('All map artwork is original, representative geography. No real mapping service, accuracy claim or third-party geographic data is included.')}<p style="font-size:10px;margin-top:15px">Hardware downloads are simulated; this bounded local illustration is bundled with the app itself.</p></section><section class="card"><h3>Connection for preparation</h3><p style="font-size:11px;margin:12px 0 17px">${state.connection.internet?'Personal internet is available.':state.internet.receive?'Using your explicitly selected provider.':'Internet is currently unavailable. Your saved area still works.'}</p>${link('Internet choices','internet','secondary small')}</section></aside></div>`;}
function internetPage(){const n=state.internet,o=n.offer,r=n.receive;return `${back()}${header('A little data goes around.','Offer your own allowance, or choose a provider. Each is a separate decision.','SHARED INTERNET')}<div class="grid two"><section class="card"><div class="card-head"><h3>${icon('upload','sm')} Offer your mobile data</h3>${pill(o?'Offering':'Off',o?'':'gray')}</div>${o?`<span class="section-label">YOUR VOLUNTARY ALLOWANCE</span><div class="large-stat" style="margin-top:14px">${(o.allowance-o.used).toFixed(0)}<span>MB remaining</span></div>${progress(Math.round(o.used/o.allowance*100),`${o.used.toFixed(1)} MB used of ${o.allowance} MB`)}<dl class="info-list" style="margin-top:25px">${info('Time remaining',`${Math.max(0,Math.ceil((o.expires-Date.now())/60000))} minutes`)}${info('Eligible recipients','Approved group phones only')}${info('Automatic stop','Allowance or time limit, whichever comes first')}</dl><div class="divider"></div>${btn('Stop offering now','stopOffer','danger small')}`:`<p style="font-size:12px;line-height:1.8;margin-bottom:22px">A measured amount, for a measured time. Starting this session never enables voice or location.</p><form id="offer-internet"><div class="form-grid">${select('Data allowance','allowance',[[100,'100 MB'],[250,'250 MB'],[500,'500 MB'],[1000,'1 GB']],250)}${select('Duration','duration',[[30,'30 minutes'],[60,'60 minutes'],[120,'120 minutes']],60)}</div>${note('This is a simulated offer. No mobile data is used. A real session would stop at the chosen limit and require a new explicit start.')}<div class="error-text"></div><button class="btn" style="margin-top:19px" type="submit">${icon('globe','sm')} Start offering</button></form>`}</section><section class="card"><div class="card-head"><h3>${icon('download','sm')} Use shared internet</h3>${pill(r?r.status:'Not in use',r?.status==='recovering'?'amber':r?'':'gray')}</div>${r?`<div class="mini-row">${avatar(person(r.provider),'large')}<div class="row-body"><b>${escape(person(r.provider).name)}</b><small>Your chosen provider · no automatic switching</small></div></div><div class="divider"></div>${r.status==='recovering'?note('Provider connection is recovering. Other internet traffic remains blocked until you stop this shared connection.','amber'):note('Simulated VPN connected. Other apps would use this selected provider. IPv4 is supported; IPv6 is blocked.')}<dl class="info-list" style="margin-top:23px">${info('Advertised allowance',`${r.remaining} MB remaining`)}${info('VPN consent','Explicitly granted · simulated')}${info('Group connection','Independent of shared internet')}</dl><div class="divider"></div>${btn('Stop & restore normal networking','stopInternet','danger small')}`:`<p style="font-size:12px;line-height:1.8;margin-bottom:22px">Choose who you use. Your phone will ask for VPN consent before connecting other apps.</p><div class="mini-row">${avatar(person('mara'),'large')}<div class="row-body"><b>${escape(person('mara').name)}</b><small>${person('mara').connected?'186 MB available · 42 minutes left':'Offer unavailable while disconnected'}</small></div>${pill(person('mara').connected?'Available':'Unavailable',person('mara').connected?'':'gray')}</div><div style="margin-top:21px">${btn('Choose Mara’s connection','vpnConsent','secondary',person('mara').connected?'':'disabled')}</div><p style="font-size:10px;margin-top:20px;line-height:1.7">The offer may expire or end. You won’t switch to someone else without choosing. Current compatibility is IPv4 only.</p>`}</section></div><div class="wide-banner"><div><h3>Your local group stays local.</h3><p>Messaging, voice and location have their own availability and consent. Internet is an optional extra, not a group membership requirement.</p></div>${link('See connection states '+icon('arrow','sm'),'connection','secondary small')}</div>`;}
function firmwarePage(){const f=state.firmware,busy=['downloading','uploading','awaiting reboot','outcome unknown'].includes(f.status)||['trial','verified trial','outcome unknown'].includes(state.radio.status)||['running','comparing'].includes(state.testing.status),n=state.nodes.find(n=>n.id===f.target)||state.nodes[0];return `${back()}${header('Keep your node in good shape.','A downloaded package is a plan. A verified new boot is an installed update.','NODE CARE')}<div class="split-layout"><div class="stack"><section class="card"><div class="card-head"><h3>${icon('node')} ${escape(n?.name||'No checked node')}</h3>${pill(n?.health||'Unavailable',n?'':'amber')}</div>${n?`<div class="node-diagram"><div class="node-unit">${icon('node')}</div><div style="padding-left:22px"><span class="section-label">CURRENTLY RUNNING</span><div class="large-stat" style="font-size:42px;margin-top:8px">${n.firmware}</div><small>${escape(n.serial)}</small></div></div><dl class="info-list">${info('Build identity',escape(n.build))}${info('Image identity',escape(n.image))}${info('Boot identity',escape(n.boot))}${info('Battery evidence','Not reported · confirm external power')}</dl>`:empty('A node needs a known identity.','Complete checked provisioning before firmware maintenance.',link('Review setup','connection','small'))}</section><section class="card"><div class="card-head"><h3>Prepare an exact package</h3>${pill(f.catalog==='never'?'Not checked':'Catalog verified','outline')}</div><form id="firmware-catalog"><div class="form-grid">${select('Release catalog','channel',[['stable','Stable'],['prerelease','Prerelease'],['nightly','Nightly'],['development','Advertised development build']],f.channel)}<div class="form-field"><label>&nbsp;</label><button class="btn secondary" type="submit" ${!owner()||busy?'disabled':''}>${icon('refresh','sm')} Check catalog</button></div></div></form>${f.package?`<div class="divider" style="margin-top:4px"></div><div class="link-line"><div><span class="section-label">COMPATIBLE · FR-v2</span><h2 style="font-size:29px;margin-top:8px">Version ${f.package.version}</h2></div>${pill(f.package.cached?'Verified & cached':'Verified package')}</div><p style="font-size:11px;line-height:1.8;margin:15px 0">${f.channel==='development'?'Development build · uncommitted-source qualification must be inspected before real use.':'Connection recovery refinements and clearer boot-state reporting. Synthetic release notes for this experiment.'}</p><dl class="info-list">${info('Build',f.package.build)}${info('Size / date',`${f.package.size} MiB · ${f.package.date}`)}${info('Source identity','Authenticated simulated release catalog')}${info('Image',f.package.image)}</dl><div style="margin-top:19px">${!f.package.cached?btn('Download & verify package','downloadFirmware','small',busy?'disabled':''):btn('Review installation','installReview','small',!owner()||busy?'disabled':'')}</div>`:`${note('No catalog has been checked. An absent response is not evidence that your node is up to date. Cached compatible packages can be used offline.')}`}${['downloading','uploading','awaiting reboot'].includes(f.status)?`<div style="margin-top:20px">${progress(f.progress,f.status)}</div>${f.status!=='awaiting reboot'?btn('Cancel preparation','cancelFirmware','secondary small','style="margin-top:15px"'):note('Activation has begun. Cancellation is unavailable; waiting for an authenticated new boot.')}`:''}${f.status==='outcome unknown'?`<div style="margin-top:20px">${note('Activation was sent, but no verified boot returned. Do not assume failure, rollback or successful installation.','amber')}${btn('Recheck running node','recheckFirmware','small')}</div>`:''}${f.status==='complete'?`<div style="margin-top:20px">${note('Verified new boot matches the exact selected image. Installation complete in this simulation.')}</div>`:''}</section></div><aside class="stack"><section class="card"><h3>A deliberate interruption</h3><p style="font-size:11px;line-height:1.9;margin:14px 0 20px">Installing can interrupt the local link, voice and transfers. Your phone identity, membership and conversation remain stored. Microphones return muted.</p><ol class="step-list"><li><span class="step-number">1</span><div><b>Check & download</b><small>Verify compatibility and the exact package.</small></div></li><li><span class="step-number">2</span><div><b>Choose one named node</b><small>Confirm power and disruption.</small></div></li><li><span class="step-number">3</span><div><b>Confirm its new boot</b><small>Upload completion isn’t enough.</small></div></li></ol></section><section class="card"><span class="section-label">EXTERNAL RECOVERY</span><h2 style="font-size:25px;margin:12px 0">Some repairs need a cable.</h2><p style="font-size:11px;line-height:1.8">Unsupported bootloaders and partition layouts need one-time trusted USB provisioning or recovery. Wireless updates cannot replace that process.</p><div style="margin-top:17px">${actionLink('Recovery guidance','usbGuidance')}</div></section></aside></div>`;}
function radioPage(){const r=state.radio,c=state.nodes[0]?.channel||6;return `${back()}${header('Find a clearer conversation.','Change one complete setting, check both nodes, and keep a way back.','RADIO SETTINGS')}<div class="grid two"><section class="card"><div class="card-head"><h3>The checked two-node link</h3>${pill(r.reportsVerified?'Matching reports':'Needs recheck',r.reportsVerified?'':'amber')}</div><div class="node-diagram"><div class="node-unit">${icon('node')}</div><div class="node-line"></div><div class="node-unit">${icon('node')}</div></div><dl class="info-list">${info('Applied channel',`Channel ${c}`)}${info('Centre / width',`${2407+c*5} MHz · 20 MHz`)}${info('Transmit power','Unchanged · not configurable here')}${info('Reports',r.reportsVerified?'Fresh associated reports agree':'Uncertain · do not infer applied setting')}</dl><div class="divider"></div><form id="radio-proposal">${select('Propose a supported complete setting','channel',[[1,'Channel 1 · 2412 MHz · 20 MHz'],[6,'Channel 6 · 2437 MHz · 20 MHz'],[11,'Channel 11 · 2462 MHz · 20 MHz']],r.proposed)}<button class="btn secondary small" type="submit" ${!owner()?'disabled':''}>Save proposal</button></form></section><section class="card"><div class="card-head"><h3>Try, verify, commit</h3>${pill(r.status,r.status==='outcome unknown'?'amber':'outline')}</div><p style="font-size:12px;line-height:1.8">A trial pauses calls and transfers. Keep both nodes powered. An uncommitted setting rolls back after 30 seconds.</p><ol class="step-list"><li class="${r.status==='proposed'?'active':''}"><span class="step-number">1</span><div><b>Propose channel ${r.proposed}</b><small>Complete setting, permitted by checked firmware.</small></div></li><li class="${r.status==='trial'?'active':''}"><span class="step-number">2</span><div><b>Trial & verify both nodes</b><small>Changed identity or boot invalidates the operation.</small></div></li><li class="${r.status==='verified trial'?'active':''}"><span class="step-number">3</span><div><b>Commit the checked result</b><small>Otherwise restore the starting channel.</small></div></li></ol>${r.status==='trial'?`${progress(r.progress,'Checking both node reports')}<div style="margin-top:15px">${btn('Cancel & restore','rollbackRadio','secondary small')}</div>`:r.status==='verified trial'?`${note(`Both nodes verified. Commit within ${Math.max(0,Math.ceil((r.expires-Date.now())/1000))} seconds, or restore.`)}<div style="display:flex;gap:9px;margin-top:18px">${btn('Commit this setting','commitRadio','small')}${btn('Restore baseline','rollbackRadio','secondary small')}</div>`:r.status==='outcome unknown'?`${note('The applied setting is unknown. Mutation is blocked until fresh status is inspected.','amber')}${btn('Recheck both nodes','recheckRadio','small')}`:btn('Begin bounded trial','trialRadio','',!owner()||r.status!=='proposed'?'disabled':'')}</section></div><section class="card" style="margin-top:20px"><div class="card-head"><h3>${icon('test','sm')} Compare supported channels</h3>${pill('SIMULATED MEASUREMENTS','outline')}</div><p style="font-size:12px;line-height:1.8">Keep antennas and positions still. Both phones must permit tests; shared internet must be stopped. Reliability is ranked first, then median rate in the slower direction. This is link performance, not a noise scan.</p>${r.comparison?`<div class="table-wrap" style="margin-top:20px"><table><thead><tr><th>Channel</th><th>Reliable runs</th><th>Slower direction</th><th>Evidence</th></tr></thead><tbody>${r.comparison.samples.map(x=>`<tr><td>${x.channel}</td><td>${x.reliability}</td><td>${x.rate} kbit/s</td><td>${x.status}</td></tr>`).join('')}</tbody></table></div><div style="margin-top:20px">${note(r.comparison.restored?'Starting-channel retest and restoration confirmed. Channel 11 is a supported recommendation; applying it is a separate trial.':'Restoration unknown. Recommendation suppressed; recheck before further traffic.',r.comparison.restored?'':'amber')}</div>${r.comparison.recommendation?`<div style="margin-top:16px">${btn('Propose recommended channel 11','recommendedRadio','secondary small')}</div>`:''}`:''}<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:21px">${link('Test permissions','measurements','secondary small')}${btn(state.testing.status==='comparing'?'Comparison running…':'Compare channels','compareChannels','small',state.testing.status!=='idle'?'disabled':'')}${state.testing.status==='comparing'?btn('Stop & restore','stopTest','danger small'):''}</div>${state.testing.status==='comparing'?progress(state.testing.progress,state.testing.stage):''}<p style="font-size:10px;margin-top:17px;line-height:1.8">A real comparison can take up to 14 minutes plus restoration and needs foreground operation. This prototype compresses time. Closing unexpectedly may leave a trial channel needing inspection.</p></section>`;}
function measurementsPage(){const t=state.testing,running=['running','comparing'].includes(t.status);return `${back()}${header('A moment, measured.','Keep the result with its conditions. One test is never a promise of range.','CONNECTION MEASUREMENTS',btn(icon('download','sm')+' Export results','exportMeasurements','secondary',!t.results.length?'disabled':''))}<div class="split-layout"><div class="stack"><section class="card"><div class="card-head"><h3>${icon('test','sm')} Bidirectional payload test</h3>${pill(running?'IN PROGRESS':'READY WHEN YOU ARE',running?'':'outline')}</div><div class="mini-row">${avatar(person('mara'),'large')}<div class="row-body"><b>${escape(person('mara').name)}</b><small>Approved peer · temporary test permission ${t.peerPermissionUntil>Date.now()?'available':'expired'}</small></div>${icon('double')}</div>${toggle('Accept tests for 15 minutes','Permission alone does not start any test.','testPermission',!!t.permissionUntil&&t.permissionUntil>Date.now())}<div style="margin-top:20px">${note('A test pauses calls and transfers; microphones return muted. Shared internet must be stopped. No position acquisition starts automatically.')}</div>${running?`<div style="margin-top:23px">${progress(t.progress,t.stage)}<dl class="info-list" style="margin-top:20px">${info('Transferred application bytes',`${Math.round(t.progress*13107).toLocaleString()} bytes`)}${info('Observed rate · simulation',t.progress<20?'Warmup · not measured':t.progress<55?'412 kbit/s →':'468 kbit/s ←')}</dl><div style="margin-top:22px">${btn('Stop & keep partial result','stopTest','danger small')}</div></div>`:`<div style="margin-top:23px">${btn('Review & start test','testReview')}</div>`}</section><section class="card"><div class="card-head"><h3>Recorded moments</h3>${pill(`${t.results.length} / 100`,'outline')}</div>${t.results.length?`<div class="table-wrap"><table><thead><tr><th>When / state</th><th>You → Mara</th><th>Mara → you</th><th>Channel</th><th></th></tr></thead><tbody>${t.results.map(r=>`<tr><td>${time(r.time)}<br><small>${r.status}</small></td><td>${r.upload??'—'} ${r.upload?'kbit/s':''}</td><td>${r.download??'—'} ${r.download?'kbit/s':''}</td><td>${r.channel} / ${r.width} MHz</td><td>${actionLink('Inspect','testResult',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Every test tells a small story.','Complete or cancel a test to keep its result here. Missing directions stay unknown, never zero.')}<div class="divider"></div><div class="link-line">${actionLink('Compare recorded conditions','compareResults')}${btn('Export CSV','exportCSV','secondary small',!t.results.length?'disabled':'')}</div></section></div><aside class="stack"><section class="card"><h3>A bounded observation</h3><p style="font-size:11px;line-height:1.9;margin-top:14px">Each direction has a two-second warmup and up to ten seconds of measurement, with overall time and byte bounds. A byte-limited run is labeled. Phone positions only appear if already shared; they are a proxy for carried nodes.</p><div class="divider"></div><dl class="info-list">${info('Historical signal','Direction-specific, when recorded')}${info('Missing position','Remains unknown')}${info('Cancellation','Retain partial measurements')}${info('Exports','May contain shared positions & device context')}</dl></section><section class="card"><span class="section-label">FROM OBSERVATION TO ASSUMPTION</span><h2 style="font-size:25px;margin:12px 0">Plan a little breathing room.</h2><p style="font-size:11px;line-height:1.8">Use a recorded result as a starting point, then explore talkers, transfers and reserve capacity.</p><div style="margin-top:18px">${link('Open capacity planner '+icon('arrow','sm'),'planner','secondary small')}</div></section></aside></div>`;}
function plannerPage(){let result=plannerResult;try{result=result||planCapacity(plannerInputs);}catch{}const p=plannerInputs;return `${back()}${header('Room for the whole group.','Change the assumptions. See the arithmetic. Keep the uncertainty in view.','CAPACITY PLANNER',btn(icon('download','sm')+' Export scenario','exportPlan','secondary'))}<div class="split-layout"><section class="card"><form id="planner-form"><div class="card-head"><h3>Your working assumptions</h3>${pill(p.historical?'Historical starting rate':'Assumed rates','outline')}</div><div class="form-grid">${field('Upload rate · kbit/s','upload',p.upload,'number','min="1" max="100000" step="1"')}${field('Download rate · kbit/s','download',p.download,'number','min="1" max="100000" step="1"')}${field('Phones in the group','members',p.members,'number','min="1" max="5"')}${field('Concurrent talkers','talkers',p.talkers,'number','min="0" max="5"')}${field('Voice per talker · kbit/s','voiceRate',p.voiceRate,'number','min="4" max="128"')}${field('Packet / contention multiplier','overhead',p.overhead,'number','min="1" max="4" step="0.05"')}${field('Position interval · seconds','interval',p.interval,'number','min="1" max="3600"')}${field('240-byte messages per minute','messages',p.messages,'number','min="0" max="120"')}${field('Assumed hop cost','hops',p.hops,'number','min="1" max="5"')}${field('Reserve capacity · %','reserve',p.reserve,'number','min="0" max="90"')}${field('Other traffic · kbit/s','other',p.other,'number','min="0" max="100000"')}${field('Donor traffic · kbit/s','donor',p.donor,'number','min="0" max="100000"')}${field('Photo size · MiB','photo',p.photo,'number','min="0.01" max="256" step="0.01"')}${field('Offline area · MiB','map',p.map,'number','min="1" max="256"')}${field('Web page · MiB','web',p.web,'number','min="0.01" max="64" step="0.01"')}</div>${note('Voice packet rate is folded into the overhead multiplier. Positions assume 128-byte updates. Hypothetical hops are a planning input, not delivered routed-network functionality.')}<div class="error-text"></div><button type="submit" class="btn" style="margin-top:20px">Recalculate scenario</button></form></section><aside class="stack"><section class="card network-card"><span class="section-label">ESTIMATED AVAILABLE CAPACITY</span><div class="large-stat" style="margin-top:20px;color:#f0f5e3">${result?result.available.toFixed(0):'—'}<span style="color:#b8cbad">kbit/s</span></div><p style="font-size:11px;line-height:1.8;margin-top:15px">After reserve, hop cost and other traffic. This is a calculation, not live measured capacity.</p><div class="network-stats"><div><b>${result?result.talkers:'—'}</b><small>ARITHMETIC TALKERS</small></div><div><b>${result?result.total.toFixed(0):'—'}</b><small>DEMAND · kbit/s</small></div><div><b>${result?result.remaining.toFixed(0):'—'}</b><small>LEFT · kbit/s</small></div></div></section>${result?`<section class="card"><h3>Where the room goes</h3><div class="capacity-bar"><span style="width:${Math.min(95,result.voice/Math.max(1,result.available)*100)}%;background:#537c4c"></span><span style="width:${Math.min(8,result.location/Math.max(1,result.available)*100)}%;background:#b7aa78"></span><span style="width:2%;background:#89a8ae"></span></div><div class="legend"><span><i style="background:#537c4c"></i>Voice</span><span><i style="background:#b7aa78"></i>Location</span><span><i style="background:#89a8ae"></i>Text</span></div><dl class="info-list" style="margin-top:23px">${info('Voice',`${result.voice.toFixed(1)} kbit/s`)}${info('Location',`${result.location.toFixed(2)} kbit/s`)}${info('Text',`${result.text.toFixed(2)} kbit/s`)}${info('Sensitivity range',`${result.low.toFixed(0)}–${result.high.toFixed(0)} kbit/s`)}</dl><div class="divider"></div><h4>Transfer-time lower bounds</h4><dl class="info-list" style="margin-top:16px">${info('Photo',result.photoSeconds?`${Math.ceil(result.photoSeconds)} seconds`:'No spare capacity')}${info('Map',result.mapSeconds?`${Math.ceil(result.mapSeconds/60)} minutes`:'No spare capacity')}${info('Web page',result.webSeconds?`${Math.ceil(result.webSeconds)} seconds`:'No spare capacity')}</dl><p style="font-size:10px;line-height:1.8;margin-top:18px">The 65–90% sensitivity range explores extra contention. No latency, loss, speech quality or range acceptance is implied.</p></section>`:''}</aside></div>`;}
function settingsPage(){const p=state.preferences;return `${back()}${header('Make yourself at home.','Small preferences, saved on this phone. Privacy choices stay separate.','PREFERENCES')}<div class="grid two"><section class="card"><div class="card-head"><h3>${icon('sun','sm')} Light & distance</h3>${pill(p.state,p.state==='failed'?'amber':'outline')}</div><form id="preferences-form">${select('Appearance','appearance',[['standard','Standard · warm daylight'],['lowlight','Low light · quiet greens']],p.appearance)}${select('Distance units','units',[['metric','Metric · metres & kilometres'],['imperial','Imperial · feet & miles']],p.units)}<div class="error-text"></div><button class="btn small" type="submit">Save preferences</button></form>${p.state==='failed'?`<div style="margin-top:18px">${note('Last confirmed preferences remain active. Check storage availability, then retry.','amber')}</div>`:''}<div class="divider"></div>${actionLink('Reload confirmed preferences','reloadPreferences')}</section><section class="card"><div class="card-head"><h3>${icon('bell','sm')} Quiet, private alerts</h3>${pill(p.alertPermission,'outline')}</div>${toggle('New message alerts','No names, message text, group names or position previews.','alerts',p.alerts)}<p style="font-size:11px;line-height:1.8;margin-top:17px">Only newly stored messages are eligible after enabling. Missed messages are not replayed. Active voice, connection and internet services have separate required controls.</p><div class="divider"></div><dl class="info-list">${info('Saved preference',p.alerts?'Enabled':'Off')}${info('Effective permission',p.alertPermission==='granted'?'Allowed · simulated':p.alertPermission==='denied'?'Denied · recover in system settings':'Not requested')}${info('System quiet mode','Not reported in browser')}${info('Optional voice / connection alerts','Planned, not available')}</dl><div style="margin-top:18px">${actionLink('Permission recovery','permissionHelp')}</div></section><section class="card"><div class="card-head"><h3>Your phone identity</h3>${icon('phone','sm')}</div><div class="mini-row">${avatar({...state.self,color:'sage'},'large')}<div class="row-body"><b>${escape(state.self.name)}</b><small>The name can change. This identity stays.</small></div>${btn('Edit','identity','secondary small')}</div><div class="code" style="margin-top:20px">${escape(state.self.identity)}</div><div style="display:flex;gap:15px;flex-wrap:wrap;margin-top:18px">${actionLink('Check name save','checkName')}${actionLink('Repair name metadata','repairNameConfirm')}</div></section><section class="card"><div class="card-head"><h3>Local care & recovery</h3>${icon('shield','sm')}</div><p style="font-size:11px;line-height:1.8">Reset only invalid preference data. Memberships, messages and identities belong to you and stay intact.</p><div class="divider"></div><div style="display:grid;gap:20px">${actionLink('Reset local preferences','resetPreferencesConfirm')}<a class="text-btn" href="#diagnostics">Collect a redacted status report ${icon('arrow','sm')}</a><a class="text-btn" href="#onboarding">Create or join another group ${icon('arrow','sm')}</a><a class="text-btn" href="#operator">Advanced operator workspace ${icon('arrow','sm')}</a></div></section></div>`;}
function diagnosticsPage(){return `${back()}${header('Useful details. Less personal detail.','Collect a local snapshot, inspect every line, and decide where it goes.','DIAGNOSTICS',btn(icon('refresh','sm')+' Collect snapshot','diagnostics','secondary'))}<div class="split-layout"><section class="card"><div class="card-head"><h3>Exact report preview</h3>${pill(state.diagnostics?'Ready to review':'Not collected','outline')}</div>${state.diagnostics?`<pre class="pre" id="diagnostic-report">${escape(JSON.stringify(state.diagnostics,null,2))}</pre><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:20px">${btn(icon('copy','sm')+' Copy report','copyDiagnostic','secondary small')}${btn(icon('download','sm')+' Save JSON','exportDiagnostic','small')}${btn('Clear temporary report','clearDiagnostics','secondary small')}</div>`:empty('A snapshot, only when you ask.','Collection never reconnects, starts a test, grants permission, or uploads anything.',btn('Collect local snapshot','diagnostics','small'))}</section><aside class="stack"><section class="card"><h3>Private details stay out.</h3><p style="font-size:11px;line-height:1.9;margin-top:14px">Names, full identities, messages, invitations, keys, addresses and coordinates are excluded. The report includes bounded counts, component states, registered capabilities and storage availability.</p><div class="divider"></div>${note('Unmeasured values remain unmeasured. Registered capabilities do not establish physical function or security acceptance.')}<p style="font-size:10px;line-height:1.8;margin-top:18px">Only bounded collection-event codes are included. A gap marker indicates dropped events; this is not a system-log collector.</p></section></aside></div>`;}
function onboardingPage(){return `<div class="onboarding-layout"><div class="onboarding-panel"><div class="eyebrow">NO ACCOUNT. JUST YOUR PEOPLE.</div><h1>Go a little further.<br>Stay a little closer.</h1><p>Bring a trusted group together with local radio nodes. Messages, voices and a sense of where everyone is—even beyond internet coverage.</p><button class="choice-card" data-action="createGroup"><div class="status-icon">${icon('people')}</div><div class="body"><h3>Make a private group</h3><p>Start small. Invite the people you trust.</p></div>${icon('arrow','sm')}</button><a class="choice-card" href="#join"><div class="status-icon">${icon('lock')}</div><div class="body"><h3>I have an invitation</h3><p>Compare identities and ask to join.</p></div>${icon('arrow','sm')}</a><a class="choice-card" href="#map"><div class="status-icon">${icon('map')}</div><div class="body"><h3>Just find my bearings</h3><p>Explore the bundled local map, offline.</p></div>${icon('arrow','sm')}</a><p style="font-size:10px;margin-top:25px;line-height:1.8">${icon('shield','sm').replace('class="icon sm"','class="icon sm" style="display:inline;vertical-align:middle;margin-right:4px"')}No hidden microphone, location or internet-sharing consent.</p></div><div class="onboarding-art"><div class="art-title">Good company.<br>Open country.</div><div class="map-surface">${terrainSVG()}</div><div style="position:absolute;bottom:25px;left:25px;right:25px;padding:18px;background:#f8f9ecdc;backdrop-filter:blur(5px);border-radius:17px"><div class="avatar-stack">${['Alex Morgan','Mara Chen','Eli Thompson'].map((name,i)=>avatar({name,color:['sage','rust','blue'][i]})).join('')}</div><p style="font-size:10px;margin-top:10px;color:#536e48">A small group. A local connection. Plenty of possibility.</p></div></div></div>`;}
function joinPage(){const r=state.request;return `${back('First steps','onboarding')}${header('There’s room for a familiar face.','An invitation opens a request. Approval makes your phone a member.','JOIN A PRIVATE GROUP')}<div class="split-layout"><section class="card">${!r?`<form id="inspect-invite"><h3 style="margin-bottom:23px">Your private invitation</h3>${field('Your display name','joinName',state.self.name,'text','maxlength="96" autocomplete="off"')}<div class="form-field"><label for="invite-code">Complete invitation value</label><textarea id="invite-code" name="code" placeholder="AUMA-INVITE-…" required></textarea><small>Use the complete value supplied by the owner. A recovery code is different.</small></div><div class="error-text"></div><button class="btn" type="submit">Inspect invitation</button></form>`:`<div class="card-head"><h3>${escape(r.group)}</h3>${pill(r.stage==='pending'?'Awaiting approval':r.stage==='offline'?'Offline exchange':'Invitation ready',r.stage==='pending'?'amber':'')}</div><dl class="info-list">${info('Owner',escape(r.owner))}${info('Request expiry',time(r.expires))}${info('Your persistent identity',escape(r.identity))}</dl><h4 style="margin-top:22px;margin-bottom:10px">Compare the owner’s identity</h4><div class="code">${escape(r.ownerIdentity)}</div>${r.stage==='pending'?`<div style="margin-top:22px">${note('Your request is pending. This phone cannot access approved-member features yet. The synthetic owner will answer shortly.')}${btn('Cancel request','cancelRequest','secondary small')}</div>`:r.stage==='offline'?`<h4 style="margin:20px 0 10px">Pass this request to the owner</h4><div class="code">${escape(state.offlineExchange.request)}</div><div style="margin-top:12px">${btn('Copy request','copyOfflineRequest','secondary small')}</div><form id="offline-approval" style="margin-top:23px"><div class="form-field"><label for="approval">Import returned approval</label><textarea id="approval" name="code" placeholder="AUMA-APPROVAL:…" required></textarea><small>The approval must include this exact phone identity.</small></div><button class="btn small" type="submit">Verify & save approval</button></form>`:`<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:24px">${btn('Request membership','requestAdmission')}${btn('Use offline exchange','offlineRequest','secondary')}</div>`}<div class="divider"></div>${actionLink('Cancel & leave this request','cancelRequest')}`}</section><aside class="stack"><section class="card"><h3>A name is not an identity.</h3><p style="font-size:11px;line-height:1.9;margin-top:15px">Compare the complete identity with the owner’s phone. The group has a maximum of five approved phones. Invitations are short-lived and can expire or be consumed.</p><div class="divider"></div>${note('After approval, your membership is saved. A new radio node still needs trusted external USB provisioning before it can reach the group.')}</section></aside></div>`;}
function roadmapPage(){const items=[['A network that carries itself.','Planned / separate acceptance','Autonomous authenticated multi-hop forwarding, phone-free relays, non-overlapping routed networks, partition survival, multiple independently authorized phones per node, and stable addressing across internet-provider changes.'],['A fuller operator’s toolkit.','Planned','Unified offline browser and command-line administration, complete configuration conflicts, logs, backup and restore, resets, and physical recovery. Current controls cover narrower checked connections, radio changes and updates.'],['Health over time.','Planned','Continuous link-health histories, loss and latency variation, and route selection or failover driven by validated measurements. A signal observation and a bounded throughput test do not deliver those guarantees.'],['A voice that holds up in the field.','Physical acceptance required','Validated noise and echo suppression, adaptive playout, first-syllable preservation and bounded outage recovery. Intended-speaker extraction remains a separate investigation; basic speech activity detection does not identify a person.'],['Ideas for another day.','Exploratory','Optional song and artist metadata, not music streaming or synchronized playback. Camera and video sharing, saved waypoints, direct messages, read receipts and cloud accounts are not current baseline features.'],['Promises earned outdoors.','Evidence required','Range, endurance, device support, security approval and release readiness need real physical evidence. No kilometre-scale range or multi-day operation guarantee is made by this prototype.']];return `${back()}${header('A clear horizon.','What this experience can show, and what still needs to be built or proved.','NOW & NEXT')}<div class="roadmap-grid">${items.map(([title,status,text])=>`<section class="card">${pill(status,'outline')}<h3>${title}</h3><p>${text}</p></section>`).join('')}</div>`;}
function operatorPage(){const o=state.operator;return `${back('Preferences','settings')}${header('The operator’s workbench.','Explicit local experiments, separate from ordinary group use.','ADVANCED · SIMULATED ONLY')}<div class="operator-grid"><section class="card"><div class="card-head"><h3>Local capability check</h3>${pill('NO REAL DEVICE ACCESS','amber')}</div><dl class="info-list">${info('Nearby-device access','Unsupported in this browser')}${info('Own position','Simulated · '+state.location.permission)}${info('Audio input / output','Simulated · no actual capture')}${info('Native service / VPN','Simulated · unavailable here')}</dl><div class="divider"></div><p style="font-size:11px;margin-bottom:15px">A local recording check is bounded to 30 seconds and never joins group voice. No audio bytes are recorded in this experiment.</p>${btn(o.recording?'Stop local check':'Start 30-second local check',o.recording?'stopRecord':'record','secondary small')}${o.recording?progress(Math.min(100,Math.round((30000-(o.recordUntil-Date.now()))/300)),'Simulated recording · local only'):''}<div style="margin-top:15px">${actionLink('Playback simulated result','playback')}</div></section><section class="card"><div class="card-head"><h3>Legacy nearby-node tools</h3>${pill(o.legacy?'Connected':'Off','outline')}</div><p style="font-size:11px;line-height:1.8;margin-bottom:17px">This path cannot grant authenticated phone-group membership. Legacy node receipts are distinct from current phone receipts. Very old retries can outlive on-node duplicate detection.</p><div style="display:flex;gap:9px;flex-wrap:wrap">${btn(o.legacy?'Disconnect legacy node':'Choose & reconnect legacy node','legacyConnect','secondary small')}${btn('Refresh observations','legacyRefresh','secondary small')}</div>${o.legacy?`<dl class="info-list" style="margin-top:20px">${info('Identity','legacy:EF-09:37 (simulated)')}${info('Radio / storage','Already provisioned · last eight messages')}</dl><form id="legacy-form" style="margin-top:20px">${field('Bounded legacy text','text','','text','required')}<button class="btn small" type="submit">Send to legacy node</button></form>${o.legacyHistory.map(x=>`<div class="mini-row"><div class="row-body"><b>${escape(x.text)}</b><small>${x.id} · ${x.state}</small></div>${actionLink('Retry same ID','legacyRetry',`data-id="${x.id}"`)}</div>`).join('')}`:''}</section><section class="card"><div class="card-head"><h3>Checked temporary lease</h3>${pill(o.lease?'Requested / simulated accepted':'Off','outline')}</div><p style="font-size:11px;line-height:1.8;margin-bottom:17px">A previously checked configuration can request a bounded 15-minute field connection. A request alone is not proof of node acceptance. Stale setup needs approved external repair.</p>${btn(o.lease?'Stop temporary lease':'Request checked lease','lease','secondary small')}${o.lease?`<p style="font-size:10px;margin-top:14px">Expires ${time(o.leaseExpires)} · renew explicitly after expiry.</p>`:''}</section><section class="card"><div class="card-head"><h3>Peer voice experiment</h3>${pill(o.experiment?'Active · muted':'Off','outline')}</div><p style="font-size:11px;line-height:1.8;margin-bottom:17px">Compare an independently exchanged fingerprint and short-lived local description. Synthetic counters and a held test tone do not establish speech quality.</p><div class="code">peer-fingerprint: 61A4 / 990F / 287C<br>description expires in 5 minutes · local only</div><div style="display:flex;gap:10px;margin:17px 0">${btn(o.experiment?'Stop & release experiment':'Compare & start experiment','experiment','secondary small')}</div>${o.experiment?`${select('Test signal · changing re-mutes','operator-tone',[['sine','Sine tone'],['noise','Bounded noise'],['silence','Silence']],o.tone)}${btn('Hold for simulated test tone','toneHold','small')}<p style="font-size:10px;margin-top:12px">Counters: packets 0 · audio transport unsupported in browser.</p>`:''}</section><section class="card"><div class="card-head"><h3>Two-node text bench</h3>${pill('ENGINEERING ONLY','outline')}</div><p style="font-size:11px;line-height:1.8;margin-bottom:18px">Last-eight-message node storage. Receipts here do not prove current app operation or phone delivery.</p><form id="node-bench">${select('Send from','from',[['A','Node A'],['B','Node B']],'A')}${field('Text · max 240 UTF-8 bytes','text','','text','required')}<button class="btn small" type="submit">Send bounded text</button></form>${o.nodeHistory.map(x=>`<div class="mini-row"><div class="row-body"><b>${escape(x.from)} → ${escape(x.text)}</b><small>${x.state} · ${x.id}</small></div>${actionLink('Recheck same ID','nodeRetry',`data-id="${x.id}"`)}</div>`).join('')}</section>${new URLSearchParams(location.search).has('evaluate')?evaluatorPanel():''}</div>`;}
function evaluatorPanel(){return `<section class="card"><div class="card-head"><h3>Evaluator environment controls</h3>${pill('REVIEW-ONLY URL','amber')}</div><p style="font-size:11px;line-height:1.8">Explicit interruption injection, isolated from product navigation. No hardware operations occur.</p>${[['write','Storage write fails'],['unknownSend','Message acknowledgement lost'],['unknownInstall','Firmware boot reply lost'],['restore','Restoration reply lost'],['permission','Permission denied']].map(([key,label])=>toggle(label,'Applies only to this local simulation.',`fault-${key}`,state.faults[key])).join('')}${toggle('Personal internet available','Does not enable shared internet or group traffic.','personalInternet',state.connection.internet)}<div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:19px">${btn('Node goes away','nodeLoss','secondary small')}${btn('Node returns','nodeReturn','secondary small')}${btn('Interrupt audio','voiceInterruption','secondary small')}${btn('Age peer positions','stalePositions','secondary small')}${btn('Revoke location','revokeLocation','secondary small')}${btn('Incoming member request','incomingRequest','secondary small')}${btn('Restart process','restart','danger small')}</div><p style="font-size:10px;margin-top:20px">Review-only admission value: AUMA-INVITE-FERN-RIDGE-PRIVATE-2026. Offline approval format: AUMA-APPROVAL:&lt;complete phone identity&gt;.</p></section>`;}

function openModal(title,description,body,wide=false){
 modal={title,description,body,wide,returnFocus:document.activeElement};
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><button class="icon-button close" data-action="close" aria-label="Close dialog">${icon('close','sm')}</button><header class="modal-header"><h2 id="dialog-title">${title}</h2>${description?`<p>${description}</p>`:''}</header>${body}</section></div>`;
 document.body.style.overflow='hidden';$('.modal').focus();
}
function closeModal(){const old=modal;modal=null;$('#modal-root').innerHTML='';document.body.style.overflow='';old?.returnFocus?.focus?.({preventScroll:true});}
function confirmDialog(title,description,action,label='Confirm',attrs=''){openModal(title,description,`${note('This changes only the local simulation. No hardware or external service is contacted.')}<div class="modal-footer">${btn('Keep as it is','close','secondary')}${btn(label,action,'',attrs)}</div>`);}
function showMember(memberId){const m=person(memberId),p=m.id==='self'?state.location.fix:m.position,connected=m.id==='self'?state.connection.group:m.connected;openModal(escape(m.name),`${m.id==='self'?'Your phone · ':''}${m.id===state.group?.owner?'Group owner':'Approved member'}`,`<div class="identity-head">${avatar(m,'large')}<div><h3>${connected?'Connected to group':'Approved, currently away'}</h3><small>${m.id==='self'?(state.voice.joined?'Joined voice':'Voice off'):m.voice&&connected?'On voice':'Not participating in voice'}</small></div></div><dl class="info-list">${info('Associated node',m.node?escape(state.nodes.find(n=>n.id===m.node)?.serial||'Known association, report unavailable'):'Unknown · not inferred')}${info('Position',p?`${p.lat.toFixed(5)}, ${p.lng.toFixed(5)}`:'Not published')}${p?info('Observation',`${isFresh(p)&&connected?'Fresh':'Last known'} · ±${p.accuracy} m · ${age(p.time)}`):''}${p&&state.location.fix?info('Straight-line separation',`${distanceLabel(distance(state.location.fix,p))} · based on ${isFresh(p)&&isFresh(state.location.fix)?'fresh':'last-known'} observations`):info('Separation','Unknown without both observations')}</dl><h4 style="margin:22px 0 10px">Complete phone identity</h4><div class="code">${escape(m.identity||'Unavailable')}</div>${m.id==='mara'?`<div class="divider"></div>${note('Historical checked radio report: Mara → your node −67 dBm. Original RF sample age unavailable; reverse direction unsupported. A group relationship is not proof of a direct radio path.')}`:''}<div class="modal-footer">${p?btn('Focus on map','focusMember','secondary',`data-id="${m.id}"`):''}${owner()&&m.id!=='self'?btn('Remove member','removeMemberConfirm','danger',`data-id="${m.id}"`):btn('Done','close','secondary')}</div>`);}
function distance(a,b){const rad=n=>n*Math.PI/180,R=6371000,dlat=rad(b.lat-a.lat),dlng=rad(b.lng-a.lng),x=Math.sin(dlat/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(dlng/2)**2;return 2*R*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
function distanceLabel(m){if(state.preferences.units==='imperial')return m>1609?`${(m/1609).toFixed(1)} mi`:`${Math.round(m*3.281)} ft`;return m>=1000?`${(m/1000).toFixed(1)} km`:`${Math.round(m)} m`;}
function showLocation(){const l=state.location,p=l.fix;openModal('Your position. Your choice.','Finding yourself and publishing your position are two different actions.',`${pill(l.status,l.sharing?'':'outline')}<dl class="info-list" style="margin-top:20px">${info('Observation',p?`${p.lat.toFixed(5)}, ${p.lng.toFixed(5)}`:'No fix yet')}${info('Accuracy & age',p?`±${p.accuracy} m · ${age(p.time)} · ${isFresh(p)&&l.acquiring?'fresh':'last known'}`:'Unmeasured')}${info('Permission',l.permission)}${info('Observation source','Synthetic / mock · not a real GPS fix')}${info('Publication',l.sharing?'To this verified group':'Off · only on this phone')}</dl><div class="divider"></div>${note('No travel track is saved. Stopping publication stops new updates; remote copies and already-sent message context cannot be erased.')}<div class="modal-footer">${btn(l.acquiring?'Refresh own position':'Find my position','locate','secondary')}${p&&!l.sharing?btn('Share with my group','shareLocation'):''}${l.acquiring||l.sharing?btn('Stop position activity','stopLocation','danger'):''}${p?btn('Clear last-known fix','clearLocation','secondary'):''}</div>`);}
function showMessage(messageId){const m=state.messages.find(x=>x.id===messageId);if(!m)return;openModal('The path of a message.','A storage receipt is not a read receipt.',`<p style="font-size:13px;line-height:1.8;color:var(--ink);padding:15px;background:var(--sage);border-radius:12px">${escape(m.text)}</p><dl class="info-list" style="margin-top:22px">${info('Immutable message ID',escape(m.id))}${info('Created by sender',time(m.time))}${info('Stored on this phone',time(m.stored))}${info('Delivery state',m.state)}${info('Future member sharing',m.future?'Eligible from creation onward':'Original recipients only')}</dl><div class="divider"></div><h4>Original intended recipients</h4>${m.recipients.map(id=>`<div class="mini-row">${avatar(person(id))}<div class="row-body"><b>${escape(person(id).name)}</b><small>${m.acks.includes(id)?'Device storage confirmed':m.state==='queued'?'Not attempted':m.state==='cancelled'?'Further retries stopped':m.state==='expired'?'Retry window exhausted':'Awaiting confirmation'}</small></div>${m.acks.includes(id)?icon('check','sm'):icon('clock','sm')}</div>`).join('')||'<p style="font-size:11px;margin-top:12px">No other members at creation.</p>'}${m.context?`<div class="divider"></div><h4>Historical context at send time</h4><p style="font-size:11px;margin-top:10px;line-height:1.8">${m.context.signal?`${m.context.signal} dBm · ${escape(m.context.direction)} · received-radio context. `:''}${m.context.position?`Position ${m.context.position.lat}, ${m.context.position.lng} · ±${m.context.position.accuracy} m · captured ${time(m.context.position.time)}. This is historical, not a live position.`:''}</p>`:''}<div class="modal-footer">${['uncertain','queued','partial'].includes(m.state)?btn('Check original send outcome','checkSend','secondary',`data-id="${m.id}"`):''}${['queued','partial','uncertain'].includes(m.state)?btn('Stop further attempts','stopSend','danger',`data-id="${m.id}"`):''}${btn('Close','close','secondary')}</div>`);}
function showPhoto(messageId){const m=state.messages.find(x=>x.id===messageId);if(!m?.photo)return;const p=m.photo;openModal('A little of what they see.',`${escape(person(m.sender).name)} · ${time(m.time)} · ${escape(m.text)}`,`${p.state==='available'?`<div class="photo-large" id="photo-inspection">${p.source==='illustration'?creekSVG():`<img src="${escape(p.source)}" alt="Group photo from ${escape(person(m.sender).name)}" onerror="this.alt='Image decode failed. The conversation is preserved.'">`}</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:15px">${btn('Enlarge / fit','zoomPhoto','secondary small')}${btn('Save available image','savePhoto','small',`data-id="${m.id}"`)}</div>`:`${note(`Announcement received. Photo bytes are ${p.state}; they are not available for inspection.`)}${progress(p.progress,p.state==='downloading'?(p.progress>=20?'Estimated a few more seconds · simulation':'Estimating after more progress'):'Waiting for an explicit load')}<div style="display:flex;gap:9px;margin-top:18px">${p.state==='downloading'?btn('Pause transfer','pausePhoto','secondary small',`data-id="${m.id}"`):btn('Load / retry photo','photoDownload','small',`data-id="${m.id}"`)}</div>`}<div class="divider"></div><dl class="info-list">${info('Announcement',m.state==='received'?'Received':m.state)}${info('Photo bytes',`${p.state} · ${Math.round(p.bytes/1024)} KiB`)}${info('Metadata','Prepared copy strips source metadata')}${info('Position context','Separate explicit consent only')}</dl><div class="modal-footer">${btn('Message delivery details','message','secondary',`data-id="${m.id}"`)}${btn('Done','close','secondary')}</div>`,true);}
function download(filename,content,type='application/json'){try{const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Browser save requested. Choose or check your download destination.');}catch{openModal('Copyable export','File saving is unavailable; copy this exact content instead.',`<textarea style="width:100%;min-height:240px" readonly>${escape(content)}</textarea>`);}}
async function copyValue(value){try{await navigator.clipboard.writeText(value);toast('Complete value copied.');}catch{openModal('Copy this complete value','Clipboard access is unavailable. Select and copy the value below.',`<textarea style="width:100%;min-height:150px" readonly>${escape(value)}</textarea>`);}}
async function preparePhoto(){
 const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png';input.style.display='none';document.body.append(input);
 input.addEventListener('change',async()=>{const file=input.files[0];input.remove();if(!file)return;try{if(!['image/jpeg','image/png'].includes(file.type))throw new Error('Choose a JPEG or PNG image.');if(file.size>64*1024*1024)throw new Error('This source exceeds 64 MiB. Choose a smaller image.');openModal('Preparing a smaller copy.','Nothing has been sent. Metadata is removed by drawing new image pixels.',`${progress(20,'Decoding source')}${btn('Cancel preparation','cancelPhoto','secondary small')}`);const token=Symbol();photoReview={token,cancelled:false};const image=await createImageBitmap(file);if(photoReview?.token!==token){image.close();return;}if(image.width*image.height>200e6){image.close();throw new Error('This image exceeds 200 megapixels.');}const scale=Math.min(1,2048/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();let quality=.85,url=canvas.toDataURL('image/jpeg',quality);while((url.length-23)*.75>1024*1024&&quality>.25){quality-=.1;url=canvas.toDataURL('image/jpeg',quality);}if((url.length-23)*.75>1024*1024)throw new Error('Prepared copy is still larger than 1 MiB. Choose a simpler or smaller photo.');photoReview={token,source:url,state:'waiting',progress:0,bytes:Math.round((url.length-23)*.75),width:canvas.width,height:canvas.height};openModal('Ready when you are.','A smaller JPEG copy, with source metadata removed. Review before sending.',`<div class="photo-large"><img src="${url}" alt="Prepared photo review"></div><p style="font-size:11px;margin-top:15px">${canvas.width} × ${canvas.height} px · ${Math.round(photoReview.bytes/1024)} KiB · no embedded source metadata</p><form id="photo-send"><div class="form-field" style="margin-top:18px"><label for="photo-caption">Accompanying message (optional)</label><textarea id="photo-caption" name="caption">${escape(state.draft.text)}</textarea></div><div class="error-text"></div><div class="modal-footer">${btn('Cancel review','cancelPhoto','secondary')}<button class="btn" type="submit">Send photo announcement</button></div></form>`,true);}catch(error){photoReview=null;openModal('That photo needs another try.',escape(error.message),`<div class="modal-footer">${btn('Close','close','secondary')}${btn('Choose another photo','choosePhoto')}</div>`);}});input.click();
}
function handleAction(action,el){const id=el?.dataset.id;
 if(action.startsWith('fault-')){const key=action.slice(6);dispatch('fault',{key,value:!state.faults[key]});return;}
 const simple=['mute','unmute','leaveVoice','disconnect','rejoin','resume','provision','forget','cancelRequest','requestAdmission','offlineRequest','clearHistory','retryDraft','stopOffer','stopInternet','downloadFirmware','cancelFirmware','recheckFirmware','trialRadio','commitRadio','rollbackRadio','recheckRadio','runTest','compareChannels','stopTest','diagnostics','clearDiagnostics','resetPreferences','checkName','repairName','nodeLoss','nodeReturn','voiceInterruption','recoverVoice','stalePositions','revokeLocation','restart','incomingRequest'];
 if(simple.includes(action)){if(dispatch(action)){closeModal();if(action==='provision')location.hash='connection';if(action==='requestAdmission'||action==='offlineRequest')location.hash='join';if(action==='joinVoice')location.hash='voice';}return;}
 switch(action){
 case 'close':closeModal();break;
 case 'identity':openModal('The name they know you by.','Your phone identity stays unchanged.',`<form id="identity-form">${field('Display name · up to 48 Unicode characters','name',state.self.name,'text','required maxlength="96"')}<div class="code">${escape(state.self.identity)}</div>${state.nameSave==='uncertain'?`<div style="margin-top:15px">${note('Previous save uncertain. Check it before editing again.','amber')}</div>`:''}<div class="error-text"></div><div class="modal-footer">${state.nameSave==='uncertain'?btn('Check saved name','checkName','secondary'):'<button class="btn" type="submit">Save name</button>'}</div></form>`);break;
 case 'member':showMember(id);break;
 case 'location':showLocation();break;
 case 'message':showMessage(id);break;
 case 'photo':showPhoto(id);break;
 case 'checkSend':case 'stopSend':if(dispatch(action,{id})){showMessage(id);}break;
 case 'photoDownload':case 'pausePhoto':if(dispatch(action,{id})){showPhoto(id);}break;
 case 'zoomPhoto':$('#photo-inspection')?.classList.toggle('zoom');break;
 case 'savePhoto':{const m=state.messages.find(m=>m.id===id);if(!m||m.photo.state!=='available')break;if(state.faults.write){openModal('The save outcome is unknown.','Check your device’s download destination before repeating. The image and conversation are still available.',btn('Return to photo','photo','secondary',`data-id="${id}"`));break;}if(m.photo.source==='illustration')download('fern-ridge-footbridge.svg',creekSVG(),'image/svg+xml');else{const a=document.createElement('a');a.download='aumanet-photo.jpg';a.href=m.photo.source;a.click();toast('Browser image save requested. Gallery integration is unavailable in this prototype.');}break;}
 case 'choosePhoto':preparePhoto();break;
 case 'cancelPhoto':photoReview=null;closeModal();toast('Photo preparation cancelled. Nothing sent.');break;
 case 'conversationOptions':openModal('A thread with a memory.','Saved on this phone. Copies on other phones stay there.',`<dl class="info-list">${info('Text capacity','2,048 UTF-8 bytes per message')}${info('Draft capacity','4,096 UTF-8 bytes')}${info('Outbox / history',`${state.messages.filter(m=>['queued','partial','uncertain'].includes(m.state)).length} of 16 pending · ${state.messages.length} of 128 records`)}${info('Catch-up window','Up to 128 eligible messages in 24 hours')}${info('Clock',state.clockTrusted?'Trusted in simulation':'Uncertain · sending blocked')}</dl><div class="divider"></div>${owner()?toggle('Future new-member history','Enabling does not expose earlier private messages.','futureHistory',state.group.historyFuture):''}<p style="font-size:11px;line-height:1.8;margin:16px 0">Older retained history can still be read while offline. Expired or evicted messages cannot be recovered by catch-up.</p><div class="modal-footer">${btn('Retry saving draft','retryDraft','secondary')}${btn('Clear local history','clearHistoryConfirm','danger')}</div>`);break;
 case 'clearHistoryConfirm':confirmDialog('Clear this phone’s history?','Your draft, pending sends and duplicate-detection records remain. Received copies on other phones are unaffected.','clearHistory','Clear local history');break;
 case 'futureHistory':dispatch('futureHistory',{value:!state.group.historyFuture});handleAction('conversationOptions');break;
 case 'createGroup':openModal('Start with a name.','This phone becomes the owner. Voice and position sharing stay off.',`<form id="create-group">${field('Your display name','personName',state.self.name,'text','required maxlength="96"')}${field('Private group name · up to 64 characters','groupName','','text','required maxlength="128" placeholder="A place, a plan, your people…"')}<div class="error-text"></div>${state.group?note('Creating another group starts a separate scope. Your earlier group, draft and conversation remain archived on this phone.','amber'):''}<div class="modal-footer"><button class="btn" type="submit">Create private group</button></div></form>`);break;
 case 'invitation':if(dispatch('invite')){const i=state.invitation;openModal('An invitation for one of your people.','Share privately. The owner still compares identity and approves admission.',`<div class="code">${escape(i.code)}</div><dl class="info-list" style="margin-top:21px">${info('Group',escape(i.group))}${info('Owner identity',escape(i.identity))}${info('Expires',time(i.expires))}</dl><div class="modal-footer">${btn('Replace invitation','invitation','secondary')}${btn('Copy complete invitation','copyInvitation')}</div>`);}break;
 case 'copyInvitation':copyValue(state.invitation.code);break;
 case 'reviewRequest':{const r=state.requests.find(x=>x.id===id);if(!r)break;openModal('Compare before you welcome.',`${escape(r.name)} would like to join ${escape(state.group.name)}.`,`${note('Compare this exact identity on the applicant’s phone. Approve only the matching request.')}<div class="code" style="margin-top:18px">${escape(r.identity)}</div><dl class="info-list" style="margin-top:20px">${info('Request ID',r.id)}${info('Expires',time(r.expires))}${info('Available places',`${5-state.members.length} of 5`)}</dl><div class="modal-footer">${btn('Decline','declineMember','secondary',`data-id="${id}"`)}${btn('Identity matches · approve','approveMember','',`data-id="${id}"`)}</div>`);break;}
 case 'approveMember':case 'declineMember':if(dispatch(action,{id}))closeModal();break;
 case 'removeMemberConfirm':confirmDialog(`Remove ${escape(person(id).name.split(' ')[0])}?`,'This revokes new group access and live position authorization. Previously received messages and photos remain on their phone.','removeMember','Remove member',`data-id="${id}"`);break;
 case 'removeMember':if(dispatch(action,{id}))closeModal();break;
 case 'groupSettings':openModal('A small group, clearly named.','Ownership transfer is not supported.',`<form id="group-name">${field('Group name','name',state.group.name,'text','required maxlength="128"')}<button class="btn small" type="submit">Save group name</button><div class="error-text"></div></form><div class="divider"></div>${toggle('Future new-member history','Only messages created after enabling are eligible.','futureHistory',state.group.historyFuture)}`);break;
 case 'offlineMembership':openModal('When the new node is out of reach.','A membership exchange can travel separately from the radio link.',`<ol class="step-list"><li><span class="step-number">1</span><div><b>Applicant inspects your invitation</b><small>They create a request carrying their persistent phone identity.</small></div></li><li><span class="step-number">2</span><div><b>Owner compares and approves</b><small>Pass back an approval bound to that exact identity.</small></div></li><li><span class="step-number">3</span><div><b>Applicant imports approval</b><small>Membership is saved; trusted USB node setup remains separate.</small></div></li></ol><form id="review-offline-request"><div class="form-field"><label for="signed-request">Request value to inspect</label><textarea name="request" id="signed-request" placeholder="AUMA-REQUEST:phone:…"></textarea></div><button class="btn small" type="submit">Inspect offline request</button></form>`);break;
 case 'copyOfflineRequest':copyValue(state.offlineExchange.request);break;
 case 'trusted':openModal('Remember this exact connection.','Bound to this phone, this group revision and this checked node.',`<form id="trusted-form"><dl class="info-list" style="margin-bottom:20px">${info('Group',escape(state.group?.name))}${info('Node',escape(state.nodes[0]?.serial||'Not provisioned'))}${info('Maximum run','2 hours · explicit resume after restart')}</dl>${select('Voice on recovery','voice',[['off','Group only · voice stays off'],['muted','Join voice, muted'],['hold','Voice ready for a fresh hold']],state.connection.trusted?.voice||'off')}${check('Publish my position during this trusted run','location',state.connection.trusted?.location||false,'Separate consent. Only for this same authorized group; no hands-free transmission or old hold can resume.')}${note('Changed group, node or approved configuration requires review again. Stopping ends automatic recovery without erasing membership or messages.')}<div class="error-text"></div><div class="modal-footer"><button class="btn" type="submit">Remember these choices</button></div></form>`);break;
 case 'disconnectConfirm':confirmDialog('Pause the connection, keep your group.','Voice, position publication, shared internet and automatic recovery end. Membership, keys, drafts and conversation remain. As owner, your dependent group members lose the live connection until recovery.','disconnect','Disconnect safely');break;
 case 'forgetConfirm':confirmDialog('Forget this connection choice?','This removes only the saved node/group recovery choices. Group membership and messages are retained.','forget','Forget saved choice');break;
 case 'recoveryCode':if(dispatch('recoveryCode'))openModal('A way back for existing members.','This short-lived code helps an already-approved phone find the owner. It is not an invitation.',`<div class="code">${escape(state.connection.recoveryCode.code)}</div><p style="font-size:11px;margin-top:16px">Expires ${time(state.connection.recoveryCode.expires)}</p><div class="modal-footer">${btn('Copy recovery code','copyRecovery')}</div>`);break;
 case 'copyRecovery':copyValue(state.connection.recoveryCode.code);break;
 case 'useRecovery':openModal('Reconnect your saved membership.','Voice and position publication remain off with ordinary rejoining.',`<form id="recovery-form"><div class="form-field"><label for="recovery-code">Complete recovery code from your owner</label><textarea id="recovery-code" name="code" required></textarea></div><div class="error-text"></div><div class="modal-footer"><button class="btn" type="submit">Check & rejoin</button></div></form>`);break;
 case 'recheckConnection':toast('Current observations refreshed. Wi-Fi, group, radio, transfers and internet remain separate.');renderApp();break;
 case 'joinVoice':if(dispatch('joinVoice'))location.hash='voice';break;
 case 'receiveAudio':dispatch('receiveAudio',{value:!state.voice.receive});break;
 case 'locate':if(dispatch('locate')){closeModal();toast(state.location.status==='Permission denied'?'Permission denied. Recover through Preferences or retry after permission is restored.':'Finding your own position. Sharing stays off.');}break;
 case 'shareLocation':if(dispatch('shareLocation'))showLocation();break;
 case 'stopLocation':case 'clearLocation':dispatch(action);showLocation();break;
 case 'follow':if(dispatch('follow')){mapView={zoom:1.6,x:0,y:0};renderApp();toast('Following your own active position. Drag the map to stop following.');}break;
 case 'locateMap':if(state.location.fix){dispatch('follow');mapView={zoom:1.6,x:0,y:0};renderApp();}else handleAction('locate');break;
 case 'focusMember':{const p=id==='self'?state.location.fix:person(id).position;if(!p){toast('No known position is available.');break;}closeModal();mapView={zoom:1.5,x:(50-p.x)*4,y:(50-p.y)*4};location.hash='map';renderApp();toast(`Focused on ${id==='self'?'your':person(id).name.split(' ')[0]+'’s'} ${isFresh(p)?'fresh':'last-known'} observation.`);break;}
 case 'focusGroup':mapView={zoom:1,x:0,y:0};dispatch('manualMap');toast(`${state.members.filter(m=>m.position&&isFresh(m.position)&&m.connected).length} fresh group positions fitted. Stale positions remain explicitly labeled.`);break;
 case 'zoomIn':mapView.zoom=Math.min(3,mapView.zoom+.25);dispatch('manualMap');break;
 case 'zoomOut':mapView.zoom=Math.max(.8,mapView.zoom-.25);dispatch('manualMap');break;
 case 'coordinates':openModal('A point to get your bearings.','Inspect temporary coordinates. This does not save or share a waypoint.',`<form id="coordinates-form"><div class="form-grid">${field('Latitude','lat',(-35.176-mapView.y*.00001).toFixed(5),'number','step="0.00001" min="-85" max="85" required')}${field('Longitude','lng',(149.024-mapView.x*.00001).toFixed(5),'number','step="0.00001" min="-180" max="180" required')}</div>${note('Representative map illustration. Entered coordinates are inspected, not used for real navigation.')}<div class="error-text"></div><div class="modal-footer"><button class="btn" type="submit">Inspect point</button></div></form>`);break;
 case 'newArea':openModal('Save a patch of the world.','Download requires internet. Existing completed coverage stays available.',`<form id="area-form">${field('Area name','name','','text','required maxlength="128" placeholder="A place to come back to"')}<div class="form-grid">${field('Latitude','lat','-35.176','number','step="0.0001" required')}${field('Longitude','lng','149.024','number','step="0.0001" required')}</div>${select('Area extent','extent',[[4,'4 × 4 km'],[10,'10 × 10 km'],[20,'20 × 20 km']],10)}${check('Include terrain and contours','terrain',true,'Increases stored size. Maximum 256 MiB per area.')}${note(`${state.areas.length} of 4 area slots used. New downloads are not usable until verified.`)}<div class="error-text"></div><div class="modal-footer"><button class="btn" type="submit">Prepare offline area</button></div></form>`);break;
 case 'pauseArea':case 'retryArea':if(dispatch(action,{id}))closeModal();break;
 case 'removeAreaConfirm':confirmDialog('Remove this saved area?','This removes only the selected geographic download. Group data and other areas remain.','removeArea','Remove area',`data-id="${id}"`);break;
 case 'removeArea':if(dispatch(action,{id}))closeModal();break;
 case 'vpnConsent':openModal('Use Mara’s shared internet?','In the native app, this requires operating-system VPN consent.',`${note('Other apps use this provider while connected. If it recovers, other internet traffic is blocked until you stop. No automatic provider switching.')}<dl class="info-list" style="margin-top:20px">${info('Provider','Mara Chen · approved phone')}${info('Remaining offer','186 MB · 42 minutes')}${info('Compatibility','IPv4 supported · IPv6 blocked')}${info('This experiment','Simulated consent · no VPN or traffic routing')}</dl><div class="modal-footer">${btn('Decline','close','secondary')}${btn('Allow simulated VPN & connect','useInternet')}</div>`);break;
 case 'useInternet':if(dispatch('useInternet',{provider:'mara'}))closeModal();break;
 case 'node':{const n=state.nodes.find(n=>n.id===id);if(n)openModal(escape(n.name),'Checked association is separate from live attachment.',`<dl class="info-list">${Object.entries(n).filter(([k])=>!['id','phone','name'].includes(k)).map(([k,v])=>info(escape(k),escape(v))).join('')}</dl><div class="divider"></div>${note('Battery and remote Wi-Fi attachment are unavailable. No zero or inferred value substitutes for missing evidence.')}`);break;}
 case 'installReview':openModal('Install on one named node.','The link, calls and transfers may be interrupted. Microphones return muted.',`<form id="install-form">${select('Checked target node','target',state.nodes.map(n=>[n.id,`${n.name} · ${n.serial}`]),state.firmware.target)}<dl class="info-list">${info('Exact package',`${state.firmware.package.version} · ${state.firmware.package.build}`)}${info('Image',escape(state.firmware.package.image))}</dl>${check('I have checked suitable power for this node','power',false,'Battery status is not reported. This is a simulated installation only.')}${note('After activation, cancellation is unavailable. Completion requires a verified new boot matching this image.')}<div class="error-text"></div><div class="modal-footer"><button class="btn" type="submit">Install simulated package</button></div></form>`);break;
 case 'usbGuidance':openModal('Recovery starts with a trusted cable.','Use the approved external USB process for unsupported setup.',`<ol class="step-list"><li><span class="step-number">1</span><div><b>Identify the exact hardware</b><small>Match hardware, bootloader and partition requirements.</small></div></li><li><span class="step-number">2</span><div><b>Preserve trusted identity data</b><small>Keep keys, memberships, phone assignments and histories.</small></div></li><li><span class="step-number">3</span><div><b>Verify the installed image and phone connection</b><small>Physical Wi-Fi/DHCP and installed-app recovery acceptance remain external requirements.</small></div></li></ol>${note('No flashing tool or real secret is included. This prototype cannot pass a hardware gate.')}`);break;
 case 'recommendedRadio':if(dispatch('proposeRadio',{channel:11}))toast('Channel 11 proposed. Begin and verify a separate trial to apply it.');break;
 case 'testPermission':dispatch('testPermission',{value:!(state.testing.permissionUntil>Date.now())});break;
 case 'testReview':confirmDialog('Measure this moment?','Both phones must permit tests. Shared internet must stop. Calls and transfers pause; microphones return muted. No GPS acquisition starts. The result remains synthetic.','runTest','Start bounded test');break;
 case 'testResult':{const r=state.testing.results.find(x=>x.id===id);if(!r)break;selectedResult=r;openModal('Keep the conditions with the result.',`${time(r.time)} · ${r.status} · synthetic measurement`, `<dl class="info-list">${info('You → Mara',r.upload?`${r.upload} kbit/s`:'Unknown / incomplete')}${info('Mara → you',r.download?`${r.download} kbit/s`:'Unknown / incomplete')}${info('Radio at measurement',`Channel ${r.channel} · ${r.width} MHz`)}${info('Recorded signal',r.signal?`${r.signal} dBm · directional`:'Unavailable')}${info('Shared start position',r.position?`${r.position.lat}, ${r.position.lng} · ±${r.position.accuracy} m`:'Not recorded; no acquisition started')}${info('Byte cap',r.capped?'Reached · measurement may be limited':'Not reached / partial')}${info('Transferred bytes',r.bytes.toLocaleString())}</dl><div class="divider"></div>${note('Current positions and radio settings never fill historical gaps. Phone separation is only a proxy for carried-node separation.')}<div class="modal-footer">${r.status==='complete'?btn('Use as planner starting rate','seedPlan'):''}${btn('Close','close','secondary')}</div>`);break;}
 case 'seedPlan':if(selectedResult){plannerInputs={...plannerDefaults,upload:selectedResult.upload,download:selectedResult.download,historical:true};plannerResult=null;closeModal();location.hash='planner';}break;
 case 'compareResults':openModal('Compare recorded conditions.','These values belong to the recorded moment, not today’s node settings.',`${state.testing.results.length?`<form id="compare-filter"><div class="form-grid">${select('Recorded channel','filterChannel',[['all','All recorded configurations'],[1,'Channel 1'],[6,'Channel 6'],[11,'Channel 11']],'all')}${select('Position observation','pointTime',[['start','Test start'],['end','Test end · may be unavailable']],'start')}</div><button class="btn secondary small" type="submit">Apply comparison</button></form><div id="comparison-results">${comparisonMarkup(state.testing.results)}</div>`:empty('No measurements retained yet.','Run or cancel a bounded test first.')}`,true);break;
 case 'exportMeasurements':openModal('Export measurement records.','Unlike a redacted diagnostic report, these records may include shared positions, device context and identities.',`${note('Only export records to a destination you choose. A browser file request follows this confirmation.','amber')}<div class="modal-footer">${btn('Cancel','close','secondary')}${btn('Save measurement JSON','confirmExportMeasurements')}</div>`);break;
 case 'confirmExportMeasurements':download('aumanet-measurements.json',JSON.stringify({synthetic:true,results:state.testing.results},null,2));closeModal();break;
 case 'exportCSV':download('aumanet-measurements.csv','synthetic,id,time,status,upload_kbps,download_kbps,channel,width_mhz,signal_dbm,latitude,longitude\n'+state.testing.results.map(r=>[true,r.id,new Date(r.time).toISOString(),r.status,r.upload??'',r.download??'',r.channel,r.width,r.signal??'',r.position?.lat??'',r.position?.lng??''].map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');break;
 case 'exportPlan':try{download('aumanet-planning-scenario.json',JSON.stringify({kind:'Assumption-based planning, not live capacity',...planCapacity(plannerInputs)},null,2));}catch(e){toast(e.message);}break;
 case 'alerts':if(!state.preferences.alerts)openModal('A quiet heads-up.','New-message alerts hide content, people, group names and positions.',`${note('This grants simulated notification permission. Native notification settings, channel blocking and quiet modes may separately prevent alerts. Missed messages will not replay.')}<div class="modal-footer">${btn('Keep alerts off','close','secondary')}${btn('Enable private alerts','enableAlerts')}</div>`);else dispatch('alerts',{value:false});break;
 case 'enableAlerts':dispatch('alerts',{value:true});closeModal();break;
 case 'permissionHelp':openModal('Permission is yours to change.','Browser prototype permissions are simulated; no system permission prompt is opened.',`<dl class="info-list">${info('Microphone',state.voice.permission)}${info('Position',state.location.permission)}${info('Alerts',state.preferences.alertPermission)}${info('VPN',state.internet.vpn)}${info('Nearby / Bluetooth','Unsupported browser integration')}</dl><div class="divider"></div>${note('In the native app, open system app settings to restore denied permissions or disabled services. Return and retry the exact action. The prototype models denial in its review-only operator environment.')}<div class="modal-footer">${btn('Retry after simulated recovery','permissionRecovered')}</div>`);break;
 case 'permissionRecovered':dispatch('fault',{key:'permission',value:false});closeModal();toast('Permission recovery acknowledged. Retry the feature explicitly; nothing was enabled.');break;
 case 'reloadPreferences':try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved?.preferences)state.preferences=saved.preferences;renderApp();toast('Confirmed local preferences reloaded.');}catch{toast('Preference storage remains inaccessible. No silent reset was performed.');}break;
 case 'resetPreferencesConfirm':confirmDialog('Reset only local preferences?','Appearance returns to standard, units to metric, and optional message alerts turn off. Membership and history remain.','resetPreferences','Reset preferences');break;
 case 'repairNameConfirm':confirmDialog('Repair name-edit metadata?','First verify current names. This short-lived confirmation repairs only edit metadata and preserves names, membership and data.','repairName','Repair verified metadata');break;
 case 'copyDiagnostic':if(state.diagnostics)copyValue(JSON.stringify(state.diagnostics,null,2));break;
 case 'exportDiagnostic':if(state.diagnostics)download('aumanet-redacted-status.json',JSON.stringify(state.diagnostics,null,2));break;
 case 'activeServices':openModal('Everything running is yours to stop.','These are independent active services. Optional message alerts are separate.',`<div class="status-list">${[['Voice',state.voice.joined,'leaveVoice'],['Position publication',state.location.sharing,'stopLocation'],['Trusted recovery run',state.connection.run,'disconnect'],['Internet offer',!!state.internet.offer,'stopOffer'],['Shared internet use',!!state.internet.receive,'stopInternet']].map(([name,on,action])=>`<div class="status-item"><div class="body"><b>${name}</b><small>${on?'Active · simulated':'Off'}</small></div>${on?btn('Stop',action,'secondary small'):pill('Off','gray')}</div>`).join('')}</div><div class="divider"></div>${note('Browser backgrounding pauses foreground-only acquisition and held transmission. No native background service exists in this experiment.')}`);break;
 case 'record':dispatch('record',{value:true});break;
 case 'stopRecord':dispatch('record',{value:false});break;
 case 'playback':toast('Simulated 30-second local check. No actual microphone recording or audio bytes are available.');break;
 case 'legacyConnect':dispatch('legacyConnect',{value:!state.operator.legacy});break;
 case 'legacyRefresh':toast(state.operator.legacy?'Legacy identity and last-eight storage refreshed. This is not a phone-group connection.':'Choose a legacy node before refreshing.');break;
 case 'legacyRetry':toast(`Rechecked original identifier ${id}. No second send intent created.`);break;
 case 'nodeRetry':toast(`Node receipt for ${id} rechecked. This is not a phone receipt.`);break;
 case 'lease':dispatch('lease',{value:!state.operator.lease});break;
 case 'experiment':dispatch('experiment',{value:!state.operator.experiment});break;
 case 'toneHold':toast('Held synthetic signal check acknowledged. No native audio transport; microphone remains muted.');break;
 case 'personalInternet':dispatch('personalInternet',{value:!state.connection.internet});break;
 default:toast('This control is unavailable in the current state.');
 }
}
function comparisonMarkup(results,point='start'){return `<div class="bar-chart">${results.slice(0,8).map(r=>`<div class="chart-column"><i style="--height:${r.upload?Math.max(3,r.upload/6):0}%"></i><i style="--height:${r.download?Math.max(3,r.download/6):0}%"></i><span>${time(r.time)} · ch ${r.channel}</span></div>`).join('')}</div><div class="legend"><span><i style="background:#688d62"></i>You → peer</span><span><i style="background:#bccba7"></i>Peer → you</span></div><div class="table-wrap"><table><thead><tr><th>Condition</th><th>Recorded signal</th><th>${point==='end'?'End':'Start'} position</th></tr></thead><tbody>${results.map(r=>`<tr><td>${time(r.time)} · ch ${r.channel}</td><td>${r.signal??'Unknown'} ${r.signal?'dBm':''}</td><td>${point==='start'&&r.position?`${r.position.lat}, ${r.position.lng} ±${r.position.accuracy} m`:'Not recorded'}</td></tr>`).join('')}</tbody></table></div><p style="font-size:10px;line-height:1.8;margin-top:14px">Missing directions are unknown. Position accuracy and source age may limit any comparison. No range guarantee follows from these observations.</p>`;}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();handleAction(el.dataset.action,el);}else if(event.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('input',event=>{if(event.target.id==='draft-text'){dispatch('draft',{text:event.target.value},false);$('#draft-status').textContent=state.draft.state==='saved'?'Draft saved on this phone':'Draft not saved · retry from options';$('#draft-bytes').textContent=`${bytes(state.draft.text)} / 2,048 bytes`;}});
document.addEventListener('change',event=>{if(event.target.id==='operator-tone')dispatch('tone',{value:event.target.value});});
document.addEventListener('submit',event=>{
 event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));let ok=false;
 switch(form.id){
 case 'compose-form':ok=dispatch('send');break;
 case 'identity-form':ok=dispatch('identity',{name:data.name});if(ok)closeModal();break;
 case 'create-group':if(dispatch('identity',{name:data.personName},false)&&dispatch('createGroup',{name:data.groupName})){closeModal();location.hash='connection';}break;
 case 'group-name':if(dispatch('renameGroup',{name:data.name}))closeModal();break;
 case 'voice-settings':dispatch('voiceSettings',data);break;
 case 'trusted-form':if(dispatch('trust',{voice:data.voice,location:data.location==='on'}))closeModal();break;
 case 'recovery-form':if(dispatch('rejoin',{code:data.code}))closeModal();break;
 case 'inspect-invite':if(dispatch('identity',{name:data.joinName},false))dispatch('inspectInvite',{code:data.code});break;
 case 'offline-approval':dispatch('offlineApproval',{code:data.code});break;
 case 'review-offline-request':{if(!owner()){toast('Only the current owner can approve an offline request.');break;}const request=data.request.trim();if(!request.startsWith('AUMA-REQUEST:phone:')){toast('Enter a complete signed-request equivalent starting AUMA-REQUEST:phone:.');break;}const identity=request.slice('AUMA-REQUEST:'.length).split(':request-')[0];openModal('Approve this exact offline identity.','Compare with the applicant’s phone before returning approval.',`<div class="code">${escape(identity)}</div>${note('Signatures are simulated. This owner approval is bound to the supplied identity.')}<form id="return-offline-approval"><input type="hidden" name="identity" value="${escape(identity)}"><div class="modal-footer"><button class="btn" type="submit">Identity matches · create approval</button></div></form>`);break;}
 case 'return-offline-approval':if(!dispatch('approveOffline',{identity:data.identity,name:'Offline applicant'}))break;const approval=`AUMA-APPROVAL:${data.identity}`;openModal('Return this approval privately.','The applicant imports it on the same phone identity.',`<div class="code">${escape(approval)}</div><div class="modal-footer"><button class="btn" data-copy="${escape(approval)}" type="button">Copy approval</button></div>`);$('[data-copy]').addEventListener('click',()=>copyValue(approval));break;
 case 'area-form':if(dispatch('downloadArea',{...data,terrain:data.terrain==='on'}))closeModal();break;
 case 'coordinates-form':{const lat=Number(data.lat),lng=Number(data.lng);if(!Number.isFinite(lat)||Math.abs(lat)>85||!Number.isFinite(lng)||Math.abs(lng)>180){toast('Coordinates are outside the supported bounds.');break;}openModal('A temporary point.','Representative geographic inspection; not a waypoint or navigation fix.',`<div class="large-stat" style="font-size:33px">${lat.toFixed(5)}<br>${lng.toFixed(5)}</div><p style="font-size:12px;margin-top:20px">This point is not saved or shared. The synthetic map does not claim real-world correspondence.</p><div class="modal-footer">${btn('Done','close','secondary')}</div>`);break;}
 case 'offer-internet':dispatch('offerInternet',data);break;
 case 'firmware-catalog':dispatch('catalog',data);break;
 case 'install-form':if(dispatch('installFirmware',{target:data.target,power:data.power==='on'}))closeModal();break;
 case 'radio-proposal':dispatch('proposeRadio',data);break;
 case 'planner-form':try{plannerInputs={...data,historical:plannerInputs.historical};plannerResult=planCapacity(plannerInputs);renderApp();toast('Scenario recalculated. Inputs remain assumptions.');}catch(e){toast(e.message);$('.error-text').textContent=e.message;}break;
 case 'preferences-form':dispatch('preferences',data);break;
 case 'photo-send':if(!photoReview){toast('Photo preparation was cancelled.');break;}if(!dispatch('draft',{text:data.caption},false))break;ok=dispatch('send',{photo:{...photoReview,token:undefined}});if(ok){photoReview=null;closeModal();location.hash='chat';toast('Photo announcement queued. Load the separate photo bytes from its message.');}break;
 case 'legacy-form':dispatch('legacyText',data);break;
 case 'node-bench':dispatch('nodeText',data);break;
 case 'compare-filter':$('#comparison-results').innerHTML=comparisonMarkup(state.testing.results.filter(r=>data.filterChannel==='all'||r.channel===Number(data.filterChannel)),data.pointTime);break;
 }
});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(photoReview)photoReview=null;closeModal();dispatch('release',{},false);}if(modal&&event.key==='Tab'){const items=$$('.modal button:not([disabled]),.modal input,.modal select,.modal textarea,.modal a[href]');if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal'))){last.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault();}}});
window.addEventListener('hashchange',()=>{if(state.voice.holding)dispatch('release',{},false);if(state.operator.recording)dispatch('record',{value:false},false);closeModal();renderApp();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('blur',()=>{if(state.voice.holding)dispatch('release');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(state.voice.holding)dispatch('release',{},false);if(state.location.acquiring&&!state.location.sharing){state.location.acquiring=false;state.location.status='Foreground acquisition paused';}if(state.operator.recording)dispatch('record',{value:false},false);persist();}else renderApp();});
function wireHold(){const button=$('#hold-talk');if(!button)return;const release=()=>{if(state.voice.holding){dispatch('release',{},false);button.classList.remove('talking');button.innerHTML=icon('mic','sm')+'Hold to talk';}};button.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();if(dispatch('hold',{},false)){button.setPointerCapture(e.pointerId);button.classList.add('talking');button.innerHTML=icon('mic','sm')+'Transmitting…';}});for(const name of ['pointerup','pointercancel','pointerleave','lostpointercapture','blur'])button.addEventListener(name,release);button.addEventListener('keydown',e=>{if((e.key===' '||e.key==='Enter')&&!e.repeat){e.preventDefault();if(dispatch('hold',{},false)){button.classList.add('talking');button.innerHTML=icon('mic','sm')+'Transmitting…';}}});button.addEventListener('keyup',release);}
function wireMaps(){for(const map of $$('[data-map]')){const art=map.querySelector('svg'),markers=map.querySelector('.map-markers');const update=()=>{const transform=`translate(${mapView.x}px,${mapView.y}px) scale(${mapView.zoom})`;art.style.transform=transform;markers.style.transform=transform;};update();let drag=null;map.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,ox:mapView.x,oy:mapView.y,moved:false};map.setPointerCapture(e.pointerId);});map.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>5)drag.moved=true;mapView.x=Math.max(-300,Math.min(300,drag.ox+dx));mapView.y=Math.max(-250,Math.min(250,drag.oy+dy));update();});map.addEventListener('pointerup',()=>{if(drag?.moved)dispatch('manualMap',{},false);else if(drag){handleAction('coordinates');}drag=null;});map.addEventListener('pointercancel',()=>drag=null);}}
function advanceOperations(){let changed=false;for(const [key,op] of Object.entries(state.ops)){if(!operationMatches(state,key,op.token))continue;const elapsed=Date.now()-op.started;
 if(key==='connect'){if(elapsed>2700){dispatch('connected',{token:op.token},false);changed=true;}else if(elapsed>1700&&state.connection.stage!==3){dispatch('connectStep',{token:op.token,stage:3},false);changed=true;}else if(elapsed>700&&state.connection.stage!==2){dispatch('connectStep',{token:op.token,stage:2},false);changed=true;}}
 else if(key==='admission'&&elapsed>7000){dispatch('admissionApproved',{token:op.token},false);location.hash='connection';changed=true;}
 else if(key==='location'&&elapsed>1200){dispatch('position',{token:op.token},false);changed=true;}
 else if(key.startsWith('area-')){const value=Math.min(100,Math.round(elapsed/110));dispatch('areaProgress',{id:key,token:op.token,progress:value},false);changed=true;}
 else if(key.startsWith('photo-')){const messageId=key.slice(6);if(!state.connection.group||!state.connection.transfer){dispatch('pausePhoto',{id:messageId},false);changed=true;continue;}const value=Math.min(100,Math.round(elapsed/(state.voice.joined?140:70)));dispatch('photoProgress',{id:messageId,token:op.token,progress:value},false);changed=true;if(modal?.title==='A little of what they see.')showPhoto(messageId);}
 else if(key==='firmware'){if(state.firmware.status==='awaiting reboot'&&elapsed>9000){dispatch('firmwareBoot',{token:op.token},false);changed=true;}else if(state.firmware.status!=='awaiting reboot'){dispatch('firmwareProgress',{token:op.token,progress:Math.min(100,Math.round(elapsed/65))},false);changed=true;}}
 else if(key==='radio'&&state.radio.status==='trial'){dispatch('radioProgress',{token:op.token,progress:Math.min(100,Math.round(elapsed/55))},false);changed=true;}
 else if(key==='test'){if(elapsed>11000){dispatch('testComplete',{token:op.token},false);changed=true;}else{dispatch('testProgress',{token:op.token,progress:Math.min(99,Math.round(elapsed/110))},false);changed=true;}}
 }
 const before=JSON.stringify({run:state.connection.run,radio:state.radio.status,recording:state.operator.recording,offer:state.internet.offer});state=transition(state,'tick');if(before!==JSON.stringify({run:state.connection.run,radio:state.radio.status,recording:state.operator.recording,offer:state.internet.offer}))changed=true;
 if(changed){persist();renderApp();}
}
setInterval(advanceOperations,500);
setInterval(()=>{if(!modal&&!document.activeElement?.matches('input,textarea,select')&&!state.voice.holding)renderApp();},15000);
persist();renderApp();
